gl. \plain \f2\lang1032\fs24 \u917 \'c5\plain \f1\lang1033\fs24  \u8016 ?\plain \f2\lang1032\fs24 \u967 \'f7\u959 \'ef\u955 \'eb\plain \f1\lang1033\fs24  \u8057 ?\plain \f2\lang1032\fs24 \u947 \'e3\u953 \'e9\u959 \'ef\u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u964 \'f4\plain \f1\lang1033\fs24  \u8056 ? \plain \f2\lang1032\fs24 \u956 \'ec\plain \f1\lang1033\fs24  \u8051 ?\plain \f2\lang1032\fs24 \u947 \'e3\u945 \'e1\plain \f1\lang1033\fs24 , Rom 1873, S. 29): \plain \f2\lang1032\fs24 \u954 \'ea\u945 \'e1\plain \f1\lang1033\fs24  \u8054 ? \plain \f2\lang1032\fs24 \u959 \'ef\plain \f1\lang1033\fs24  \u8021 ?\plain \f2\lang1032\fs24 \u964 \'f4\u969 \'f9\u962 \'f2\plain \f1\lang1033\fs24   \u7936 ?\plain \f2\lang1032\fs24 \u960 \'f0\plain \f1\lang1033\fs24  \u8051 ?\plain \f2\lang1032\fs24 \u961 \'f1\u967 \'f7\u959 \'ef\u957 \'ed\u964 \'f4\u945 \'e1\u953 \'e9\plain \f1\lang1033\fs24   \u7956 ?\plain \f2\lang1032\fs24 \u956 \'ec\u960 \'f0\u961 \'f1\u959 \'ef\u963 \'f3\u952 \'e8\u949 \'e5\u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u964 \'f4\plain \f1\lang1033\fs24  \u8182 ?\plain \f2\lang1032\fs24 \u957 \'ed\plain \f1\lang1033\fs24   \u8033 ?\plain \f2\lang1032\fs24 \u961 \'f1\u945 \'e1\plain \f1\lang1033\fs24  \u8055 ?\plain \f2\lang1032\fs24 \u969 \'f9\u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u960 \'f0\u965 \'f5\u955 \'eb\plain \f1\lang1033\fs24  \u8182 ?\plain \f2\lang1032\fs24 \u957 \'ed\plain \f1\lang1033\fs24 , \plain \f2\lang1032\fs24 \u954 \'ea\u945 \'e1\plain \f1\lang1033\fs24  \u8054 ? \plain \f2\lang1032\fs24 \u960 \'f0\u961 \'f1\u959 \'ef\u963 \'f3\plain \f1\lang1033\fs24  \-\plain \f2\lang1032\fs24 \u954 \'ea\u965 \'f5\u957 \'ed\u959 \'ef\plain \f1\lang1033\fs24  \u8166 ?\plain \f2\lang1032\fs24 \u963 \'f3\u953 \'e9\u957 \'ed\plain \f1\lang1033\fs24   \u7952 ?\plain \f2\lang1032\fs24 \u954 \'ea\u949 \'e5\plain \f1\lang1033\fs24  \u8150 ?\plain \f2\lang1032\fs24 \u963 \'f3\u949 \'e5\plain \f1\lang1033\