\pard\sl360\slmult1\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24  10. (ff. 86v\endash 93v) {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 \u8222 \'84Ephraem Graecus\ldblquote }}\plain \f1\lang1033\fs24 , \u8249 \'8bSermo de communi resurrectione, de paenitentia et de caritate, et in secundum adventum d. n. I. C.\u8250 \'9b (Ms. \plain \f2\lang1032\fs24 \u932 \'d4\u959 \'ef\plain \f1\lang1033\fs24  \u8166 ? \plain \f2\lang1032\fs24 \u956 \'ec\u945 \'e1\u954 \'ea\u945 \'e1\plain \f1\lang1033\fs24  \-\plain \f2\lang1032\fs24 \u961 \'f1\plain \f1\lang1033\fs24  \u8055 ?\plain \f2\lang1032\fs24 \u959 \'ef\u965 \'f5\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u954 \'ea\u945 \'e1\plain \f1\lang1033\fs24  \u8054 ? \plain \f2\lang1032\fs24 \u960 \'f0\u945 \'e1\u957 \'ed\plain \f1\lang1033\fs24  \-\plain \f2\lang1032\fs24 \u963 \'f3\plain \f1\lang1033\fs24  \u8057 ?\plain \f2\lang1032\fs24 \u966 \'f6\u959 \'ef\u965 \'f5\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u954 \'ea\u965 \'f5\u961 \'f1\u959 \'ef\plain \f1\lang1033\fs24  \u8166 ? \u7960 ?\plain \f2\lang1032\fs24 \u966 \'f6\u961 \'f1\u945 \'e1\plain \f1\lang1033\fs24  \u8054 ?\plain \f2\lang1032\fs24 \u956 \'ec\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u955 \'eb\plain \f1\lang1033\fs22  (\plain \f1\lang1033\fs24  \u8057 ?\plain \f1\lang1033\fs22 )\plain \f2\lang1032\fs24 \u947 \'e3\plain \f1\lang1033\fs22  (\plain \f2\lang1032\fs24 \u959 \'ef\u962 \'f2\plain \f1\lang1033\fs22 )\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u949 \'e5\plain \f1\lang1033\fs24  \u180 \'b4 [?] \plain \f2\lang1032\fs24 \u949 \'e5\plain \f1\lang1033\fs24  \u7984 ?\plain \f2\lang1032\fs24 \u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u964 \'f4\plain \f1\lang1033\fs24  \u8052 ?\plain \f2\lang1032\fs24 \u957 \'ed\plain \f1\lang1033\fs24   \u7969 ?\plain \f2\lang1032\fs24 \u956 \'ec\plain \f1\lang1033\fs24  \u8051 ?\plain \f2\lang1032\f