\pard\sl360\slmult1\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24  1. (ff. 1r\endash 19v) \u8249 \'8b{\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Nicetas Heracleensis}}\plain \f1\lang1033\fs24 , Kommentar zu\u8250 \'9b {\field{\*\fldinst HYPERLINK "hida://bezper[1].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Gregorius Nazianzenus}}\plain \f1\lang1033\fs24 , In novam dominicam; or. 44 (Ms. \plain \f2\lang1032\fs24 \u915 \'c3\u961 \'f1\u951 \'e7\u947 \'e3\u959 \'ef\u961 \'f1\plain \f1\lang1033\fs24  \u8055 ?\plain \f2\lang1032\fs24 \u959 \'ef\u965 \'f5\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u964 \'f4\u959 \'ef\plain \f1\lang1033\fs24  \u8166 ? \plain \f2\lang1032\fs24 \u952 \'e8\u949 \'e5\u959 \'ef\u955 \'eb\plain \f1\lang1033\fs24  \u8057 ?\plain \f2\lang1032\fs24 \u947 \'e3\u959 \'ef\u965 \'f5\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u955 \'eb\plain \f1\lang1033\fs24  \u8057 ?\plain \f2\lang1032\fs24 \u947 \'e3\u959 \'ef\u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u949 \'e5\plain \f1\lang1033\fs24  \u7984 ?\plain \f2\lang1032\fs24 \u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u964 \'f4\plain \f1\lang1033\fs24  \u8048 ? \u7952 ?\plain \f2\lang1032\fs24 \u947 \'e3\plain \f1\lang1033\fs24  \-\plain \f2\lang1032\fs24 \u954 \'ea\u945 \'e1\plain \f1\lang1033\fs24  \u8055 ?\plain \f2\lang1032\fs24 \u957 \'ed\u953 \'e9\u945 \'e1\plain \f1\lang1033\fs24 ), PG 36, 608\endash 621; CPG II 3010 mit Suppl. 3010.44; BHG 1021 mit Nov. Auct.; Kommentar, ed. lat. PG 127, 1409\endash 1434 (mit einigen Textabweichungen); \plain \f1\i\lang1033\fs24  inc.\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://5650[0].5666v/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 \rquote \u917 ?\u947 ?\u954 ?\u945 a\u8055 ?\u957 ?\u953 ?\u945 a \u7952 ?\u960 p\u8054 ? \u957 ?\u945 a\u959 ?\u8166 ? \u956 \'b5\u8050 ?\u957 ? \u7969 ? \u960 p\u961 ?\u8061 ?\u964 t\u951 ? \u954 ?\u945 a\u952 ?\u8055 ?\u948 d\u961 ?\u965 ?\u963 s\u953 ?\u962 ? \u954 ?\u964 t\u955 ?.}}\plain \f1\lang1033\fs24   \plain \f1\i\lang1033\fs24  des.\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u954 \'ea\u945 \'e1\plain \f1\lang1033\fs24  \u8054 ? \plain \f2\lang1032\fs24 \u959 \'ef\plain \f1\lang1033\fs24  \u8021 ?\plain \f2\lang1032\fs24 \u964 \'f4\u969 \'f9\u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u949 \'e5\plain \f1\lang1033\fs24  \u7984 ?\plain \f2\lang1032\fs24 \u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u964 \'f4\plain \f1\lang1033\fs24  \u8056 ?\plain \f2\lang1032\fs24 \u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u954 \'ea\u945 \'e1\u953 \'e9\u957 \'ed\plain \f1\lang1033\fs24  \u8056 ?\plain \f2\lang1032\fs24 \u957 \'ed\plain \f1\lang1033\fs24   \u7952 ?\plain \f2\lang1032\fs24 \u954 \'ea\u949 \'e5\plain \f1\lang1033\fs24  \u8150 ?\plain \f2\lang1032\fs24 \u957 \'ed\u959 \'ef\u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u946 \'e2\plain \f1\lang1033\fs24  \u8055 ?\plain \f2\lang1032\fs24 \u959 \'ef\u957 \'ed\plain \f1\lang1033\fs24   \u7936 ?\plain \f2\lang1032\fs24 \u960 \'f0\plain \f1\lang1033\fs24  \u8051 ?\plain \f2\lang1032\fs24 \u955 \'eb\u952 \'e8\u969 \'f9\plain \f1\lang1033\fs24  \-\plain \f2\lang1032\fs24 \u956 \'ec\u949 \'e5\u957 \'ed\plain \f1\lang1033\fs24 . \endash  Davor: (f. 1r, 2.\endash 6. Z.) Argumentum; \plain \f1\i\lang1033\fs24  inc.\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://5650[1].5666v/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 \u932 ?\u8134 ?\u962 ? \u960 p\u945 a\u957 ?\u951 ?\u947 ?\u965 ?\u961 ?\u953 ?\u954 ?\u8134 ?\u962 ? \u7984 ?\u948 d\u8051 ?\u945 a\u962 ? \u954 ?\u945 a\u8054 ? \u959 ?\u8023 ?\u964 t\u959 ?\u962 ? \u8001 ? \u955 ?\u8057 ?\u947 ?\u959 ?\u962 ? \u7952 ?\u963 s\u964 t\u8055 ? \u954 ?\u964 t\u955 ?.}}\plain \f1\lang1033\fs24   \plain \f1\i\lang1033\fs24  des.\plain \f1\lang1033\fs24 