\lang1033\fs24   \plain \f2\lang1032\fs24 \u963 \'f3\u967 \'f7\u959 \'ef\u955 \'eb\u945 \'e1\u963 \'f3\u964 \'f4\u953 \'e9\u954 \'ea\u959 \'ef\plain \f1\lang1033\fs24  \u8166 ?, \plain \f2\lang1032\fs24 \u964 \'f4\u959 \'ef\plain \f1\lang1033\fs24  \u8166 ? \u8249 \'8b\u7952 ?\plain \f2\lang1032\fs24 \u957 \'ed\plain \f1\lang1033\fs24  \u8250 \'9b \u7937 ?\plain \f2\lang1032\fs24 \u947 \'e3\plain \f1\lang1033\fs24  \u8055 ?\plain \f2\lang1032\fs24 \u959 \'ef\u953 \'e9\u962 \'f2\plain \f1\lang1033\fs24   \u8033 ?\plain \f2\lang1032\fs24 \u962 \'f2\plain \f1\lang1033\fs24   \u7936 ?\plain \f2\lang1032\fs24 \u955 \'eb\u951 \'e7\u952 \'e8\plain \f1\lang1033\fs24  \u8182 ?\plain \f2\lang1032\fs24 \u962 \'f2\plain \f1\lang1033\fs24 , \plain \f2\lang1032\fs24 \u963 \'f3\u965 \'f5\u947 \'e3\plain \f1\lang1033\fs24  \-\plain \f2\lang1032\fs24 \u947 \'e3\u961 \'f1\u945 \'e1\u966 \'f6\u949 \'e5\plain \f1\lang1033\fs24  \u8054 ?\plain \f2\lang1032\fs24 \u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u960 \'f0\u945 \'e1\u961 \'f1\plain \f1\lang1033\fs24  \u8048 ? \plain \f2\lang1032\fs24 \u916 \'c4\u945 \'e1\u957 \'ed\u953 \'e9\plain \f1\lang1033\fs24  \u8052 ?\plain \f2\lang1032\fs24 \u955 \'eb\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u956 \'ec\u959 \'ef\u957 \'ed\u945 \'e1\u967 \'f7\u959 \'ef\plain \f1\lang1033\fs24  \u8166 ? \u8172 ?\plain \f2\lang1032\fs24 \u945 \'e1\u953 \'e9\plain \f1\lang1033\fs24  \u776 ?\plain \f2\lang1032\fs24 \u952 \'e8\u951 \'e7\u957 \'ed\u959 \'ef\plain \f1\lang1033\fs24  \u8166 ? \u7936 ?\plain \f2\lang1032\fs24 \u957 \'ed\u948 \'e4\u961 \'f1\plain \f1\lang1033\fs24  \u8056 ?\plain \f2\lang1032\fs24 \u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u964 \'f4\u953 \'e9\u956 \'ec\plain \f1\lang1033\fs24  \u8055 ?\plain \f2\lang1032\fs24 \u959 \'ef\u965 \'f5\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u954 \'ea\u945 \'e1\plain \f1\lang1033\fs24  \u8054 ? \u7952 ?\plain \f2\lang1032\fs24 \u957 \'ed\u945 \'