\pard\sl360\slmult1\fi0\li0\tx360\ql\ri0\sb0\sa0\itap0 \plain \f1\b\i\lang1033\fs20 Lit\plain \f1\lang1033\fs20  \tab \plain \f1\scaps\lang1033\fs20 Stephanus-Katalog\plain \f1\lang1033\fs20 , ff. 87v\endash 88r. \endash  \plain \f1\scaps\lang1033\fs20 Hardt\plain \f1\lang1033\fs20   III, S. 236\endash 240. \endash  \plain \f1\scaps\lang1033\fs20 J. M. Pardessus\plain \f1\lang1033\fs20   (Hrsg.), Collection de lois maritimes ant\u233 \'e9rieures au XVIIIe si\u232 \'e8cle, I, Paris 1828, S. 228\endash 229. \endash  \plain \f1\scaps\lang1033\fs20 Pitra\plain \f1\lang1033\fs20 , Ius I, S. XIV. \endash  \plain \f1\scaps\lang1033\fs20 C. E. Zachariae von Lingenthal\plain \f1\lang1033\fs20   (Hrsg.), Jus Graeco-Romanum, IV. Ecloga privata aucta, Ecloga ad prochiron mutata et Epanagoge aucta, Leipzig 1865, S. 173 = \plain \f1\scaps\lang1033\fs20 I. Zepos\plain \f1\lang1033\fs20   / \plain \f1\scaps\lang1033\fs20 P. Zepos\plain \f1\lang1033\fs20   (Hrsg.), Jus Graecoromanum, VI. Epanagoge aucta, Ecloga ad prochiron mutata, Synopsis minor, Athen 1931, S. 57. \endash  \plain \f1\scaps\lang1033\fs20 W. Ashburner\plain \f1\lang1033\fs20 , \plain \f2\lang1032\fs20 \u925 \'cd\plain \f1\lang1033\fs20  \u8057 ?\plain \f2\lang1032\fs20 \u956 \'ec\u959 \'ef\u962 \'f2\plain \f1\lang1033\fs20   \u8172 ?\plain \f2\lang1032\fs20 \u959 \'ef\u948 \'e4\plain \f1\lang1033\fs20  \u8055 ?\plain \f2\lang1032\fs20 \u969 \'f9\u957 \'ed\plain \f1\lang1033\fs20   \plain \f2\lang1032\fs20 \u925 \'cd\u945 \'e1\u965 \'f5\u964 \'f4\u953 \'e9\u954 \'ea\plain \f1\lang1033\fs20  \u8057 ?\plain \f2\lang1032\fs20 \u962 \'f2\plain \f1\lang1033\fs20 . The Rhodian Sea-Law, Oxford 1909, S. XXXIX\endash XL. \endash  \plain \f1\scaps\lang1033\fs20 Hartig\plain \f1\lang1033\fs20 , S. 136, 242, 368. \endash \plain \f1\scaps\lang1033\fs20  Glauning\plain \f1\lang1033\fs20 , S. 268, 273. \endash  \plain \f1\scaps\lang1033\fs20 I. P. Medvedev \plain \f1\lang1033\fs20  (Hrsg.)\plain \f3\lang1024\fs20 , Vizantijskij Zemledel\rquote \u269 \'e8eskij zakon, S\plain \f1\lang1033\fs20  ankt Petersburg (Leningrad) 1984, S. 48, 50, 92 (Hs. benutzt). \endash  \plain \f1\scaps\lang1033\fs20 F. Sitzia \plain \f1\lang1033\fs20  (Hrsg.), Le Rhopai, Neapel 1984, S. 23\endash 25. \endash  \plain \f1\scaps\lang1033\fs20 L. Burgmann / M. Th. F\plain \f1\scaps\lang1033\fs20 \u246 \'f6\plain \f1\scaps\lang1033\fs20 gen / A. Schminck / D. Simon\plain \f1\lang1033\fs20   (Hrsg.), Repertorium der Handschriften des byzantinischen Rechts, I. Die Hand\-schriften des weltlichen Rechts (Nr. 1\endash 327) (FzbR 20), Frankfurt a. M. 1995, S. 165 (Nr. 140; falsche, unvoll\-st\u228 \'e4ndige Inhaltsangabe). \endash  \plain \f1\scaps\lang1033\fs20 Hobson\plain \f1\lang1033\fs20 , S. 261. \endash  \plain \f1\scaps\lang1033\fs20 Hajd\plain \f1\scaps\lang1033\fs20 \u250 \'fa\plain \f1\scaps\lang1033\fs20 , \plain \f1\lang1033\fs20  Sammlung, S. 26 (Anm. 38), 63 (Anm. 213), 69 (Anm. 250), 77 (Anm. 291), 89 (Anm. 352), 94.}

