\par \pard\sl360\slmult1\fi0\li0\tx360\ql\ri0\sb0\sa0\itap0 \tab (ff. 317r, 8. Z.\endash 318v, 14. Z.) II 35, ed. \plain \f1\scaps\lang1033\fs24 Guy\plain \f1\lang1033\fs24 , Apophtegmes I, S. 142\endash 146. \endash  (f. 318v, 15.\endash 16. Z.) XI 43, ed. \plain \f1\scaps\lang1033\fs24 Guy\plain \f1\lang1033\fs24 , Apophtegmes II, S. 194; \plain \f1\i\lang1033\fs24  des. mut.\plain \f1\lang1033\fs24   \u7964 ?\plain \f2\lang1032\fs24 \u955 \'eb\u949 \'e5\u947 \'e3\u949 \'e5\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u947 \'e3\plain \f1\lang1033\fs24  \u8051 ?\plain \f2\lang1032\fs24 \u961 \'f1\u969 \'f9\u957 \'ed\plain \f1\lang1033\fs24 , \u8005 ?\plain \f2\lang1032\fs24 \u964 \'f4\u953 \'e9\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u966 \'f6\u965 \'f5\u955 \'eb\u945 \'e1\u954 \'ea\plain \f1\lang1033\fs24  \u8053 ? \u7952 ?\plain \f2\lang1032\fs24 \u963 \'f3\u964 \'f4\u953 \'e9\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u964 \'f4\plain \f1\lang1033\fs24  \u8056 ? \plain \f2\lang1032\fs24 \u954 \'ea\plain \f1\lang1033\fs24  \u8051 ?\plain \f2\lang1032\fs24 \u955 \'eb\u955 \'eb\u953 \'e9\u959 \'ef\u957 \'ed\plain \f1\lang1033\fs24   (!) \plain \f2\lang1032\fs24 \u956 \'ec\u957 \'ed\u951 \'e7\u956 \'ec\u959 \'ef\plain \f1\lang1033\fs24  \-\plain \f2\lang1032\fs24 \u957 \'ed\u949 \'e5\plain \f1\lang1033\fs24  \u8059 ?\plain \f2\lang1032\fs24 \u949 \'e5\u953 \'e9\u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u964 \'f4\u959 \'ef\plain \f1\lang1033\fs24  \u8166 ? \plain \f2\lang1032\fs24 \u920 \'c8\u949 \'e5\u959 \'ef\plain \f1\lang1033\fs24  \u8166 ? [\plain \f2\lang1032\fs24 \u960 \'f0\u945 \'e1\u957 \'ed\u964 \'f4\plain \f1\lang1033\fs24  \u8057 ?\plain \f2\lang1032\fs24 \u964 \'f4\u949 \'e5\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u954 \'ea\u964 \'f4\u955 \'eb\plain \f1\lang1033\fs24 .}

