\pard\sl360\slmult1\fi0\li0\tx420\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24  15. (f. 95v, 1.\endash 4. Z.) \u8249 \'8b{\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Manuel Adramyttenus}}\plain \f1\lang1033\fs24  \u8250 \'9b,\plain \f1\lang1033\fs20   \plain \f1\lang1033\fs24  Beginn eines Briefes an einen Priester Michael (Ms. \u8249 \'8b\plain \f2\lang1032\fs24 \u928 \'d0\plain \f1\lang1033\fs24  \u8250 \'9b\plain \f2\lang1032\fs24 \u949 \'e5\u961 \'f1\plain \f1\lang1033\fs24  \u8054 ? \u7936 ?\plain \f2\lang1032\fs24 \u963 \'f3\u954 \'ea\u951 \'e7\u964 \'f4\u953 \'e9\u954 \'ea\plain \f1\lang1033\fs24  \u8182 ?\plain \f2\lang1032\fs24 \u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u946 \'e2\u961 \'f1\u969 \'f9\plain \f1\lang1033\fs24  \-\plain \f2\lang1032\fs24 \u956 \'ec\plain \f1\lang1033\fs24  \u8049 ?\plain \f2\lang1032\fs24 \u964 \'f4\u969 \'f9\u957 \'ed\plain \f1\lang1033\fs24   [\u252 \'fcber der Zeile \plain \f2\lang1032\fs24 \u964 \'f4\u961 \'f1\u959 \'ef\plain \f1\lang1033\fs24  \-\plain \f2\lang1032\fs24 \u966 \'f6\u8182 ?\u957 \'ed\plain \f1\lang1033\fs24  ] \u8249 \'8bM\u8250 \'9b\plain \f2\lang1032\fs24 \u945 \'e1\u957 \'ed\u959 \'ef\u965 \'f5\u959 \'ef\u965 \'f5\u8052 ?\u955 \'eb\plain \f1\lang1033\fs24   [!] \u8001 ? \u7944 ?\plain \f2\lang1032\fs24 \u948 \'e4\u961 \'f1\u945 \'e1\plain \f1\lang1033\fs24  \-\plain \f2\lang1032\fs24 \u956 \'ec\u965 \'f5\u964 \'f4\u964 \'f4\u951 \'e7\u957 \'ed\u8056 ?\u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u924 \'cc\u953 \'e9\u967 \'f7\u945 \'e1\u8052 ?\u955 \'eb\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u7985 ?\u949 \'e5\plain \f1\lang1033\fs24  \-\plain \f2\lang1032\fs24 \u961 \'f1\u949 \'e5\u8150 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u949 \'e5\u8022 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u960 \'f0\u961 \'f1\u8049 ?\u964 \'f4\u964 \'f4\u949 \'e5\u953 \'e9\u957 \'ed\plain \f1\lang1033\fs24 ): {\field{\*\fldinst HYPERLINK "hida://5650[0].5666v/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 \u8249 \'8b\u931 S\u8250 \'9b\u8058 ? \u960 p\u945 a\u8059 ?\u8131 ? (unter der Zeile \u7952 ?\u957 ?\u8055 ?\u959 ?\u964 t\u949 e) \u964 t\u959 ?\u8166 ? \u960 p\u965 ?\u957 ?\u952 ?\u8049 ?\u957 ?\u949 e\u963 s\u952 ?\u945 a\u953 ? \u7969 ?\u956 \'b5\u8118 ?\u962 ? \u964 t\u8048 ? \u8017 ?\u960 p\u8050 ?\u961 ? \u7969 ?\u956 \'b5\u8118 ?\u962 ?.}}\plain \f1\lang1033\fs24   Der Rest der Seite leer. \endash  (ff. 95Ar\endash 95Bv) leer.}

