\pard\sl360\slmult1\fi0\li0\tx420\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24  17. (f. 100v, 1.\endash 9. Z.) \u8249 \'8b{\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Manuel Adramyttenus}}\plain \f1\lang1033\fs24  \u8250 \'9b,\plain \f1\lang1033\fs20   \plain \f1\lang1033\fs24  Epigramma anonymum in beatum Hieronymum Castellanum e Latino in Graecum versum (Ms. \plain \f2\lang1032\fs24 \u7960 ?\u960 \'f0\u8055 ?\u947 \'e3\u961 \'f1\u945 \'e1\u956 \'ec\u956 \'ec\u945 \'e1\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u959 \'ef\u8016 ?\u954 \'ea\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u959 \'ef\u7990 ?\u948 \'e4\u8125 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u8005 ?\u964 \'f4\u959 \'ef\u965 \'f5\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u949 \'e5\u7984 ?\u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u964 \'f4\u8056 ?\u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u956 \'ec\u945 \'e1\u954 \'ea\u945 \'e1\u961 \'f1\u8055 ?\u964 \'f4\u951 \'e7\u957 \'ed\plain \f1\lang1033\fs24   \u7993 ?\plain \f2\lang1032\fs24 \u949 \'e5\u961 \'f1\u8061 ?\u957 \'ed\u965 \'f5\u956 \'ec\u959 \'ef\u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u964 \'f4\u8056 ?\u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u7952 ?\u954 \'ea\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u964 \'f4\u959 \'ef\u8166 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u922 \'ca\u945 \'e1\plain \f1\lang1033\fs24  \-\plain \f2\lang1032\fs24 \u963 \'f3\u964 \'f4\u8051 ?\u955 \'eb\u955 \'eb\u959 \'ef\u965 \'f5\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u956 \'ec\u949 \'e5\u964 \'f4\u945 \'e1\plain \f1\lang1033\fs24  \-\plain \f2\lang1032\fs24 \u946 \'e2\u955 \'eb\u951 \'e7\plain \f1\lang1033\fs24  \-\plain \f2\lang1032\fs24 \u952 \'e8\u8050 ?\u957 \'ed\plain \f1\lang1033\fs24   \u7952 ?\plain \f2\lang1032\fs24 \u954 \'ea\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u964 \'f4\u959 \'ef\u8166 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u923 \'cb\u945 \'e1\plain \f1\lang1033\fs24  \-\plain \f2\lang1032\fs24 \u964 \'f4\u953 \'e9\plain \f1\lang1033\fs24  \-\plain \f2\lang1032\fs24 \u957 \'ed\u953 \'e9\plain \f1\lang1033\fs24  \-\plain \f2\lang1032\fs24 \u954 \'ea\u959 \'ef\u8166 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u949 \'e5\u7984 ?\u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u964 \'f4\u8056 ?\plain \f1\lang1033\fs24   \u7961 ?\plain \f2\lang1032\fs24 \u955 \'eb\u955 \'eb\u951 \'e7\plain \f1\lang1033\fs24  \-\plain \f2\lang1032\fs24 \u957 \'ed\u953 \'e9\u954 \'ea\u8056 ?\u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u960 \'f0\u945 \'e1\u961 \'f1\u8125 ?\plain \f1\lang1033\fs24   \u7952 ?\plain \f2\lang1032\fs24 \u956 \'ec\u959 \'ef\u8166 ?\plain \f1\lang1033\fs24 ),\plain \f1\i\lang1033\fs24   \plain \f1\lang1033\fs24  ed. \plain \f1\scaps\lang1033\fs24 Legrand\plain \f1\lang1033\fs24 , a. O., S. 359, nach dieser Hs.; \plain \f1\i\lang1033\fs24  inc.\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u927 \'cf\u8023 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u948 \'e4\u959 \'ef\u954 \'ea\u953 \'e9\plain \f1\lang1033\fs24  \-\plain \f2\lang1032\fs24 \u956 \'ec\u8061 ?\plain \f1\lang1033\fs24  \-\plain \f2\lang1032\fs24 \u964 \'f4\u949 \'e5\u961 \'f1\u959 \'ef\u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u959 \'ef\u8016 ?\u948 \'e4\u949 \'e5\u8055 ?\u962 \'f2\plain \f1\lang1033\fs24 , \plain \f2\lang1032\fs24 \u959 \'ef\plain \f1\lang1033\fs24  \u8023 ? \plain \f2\lang1032\fs24 \u963 \'f3\u964 \'f4\u8057 ?\plain \f1\lang1033\fs24  \-\plain \f2\lang1032\fs24 \u956 \'ec\u945 \'e1\u964 \'f4\u953 \'e9\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u955 \'eb\u953 \'e9\u947 \'e3\u965 \'f5\plain \f1\lang1033\fs24  \-\plain \f2\lang1032\fs24 \u966 \'f6\u8061 ?\u957 \'ed\u8179 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u954 \'ea\u964 \'f4\u955 \'eb\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24  des.\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u948 \'e4\u8134 ?\u956 \'ec\u949 \'e5\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u952 \'e8\u959 \'ef\u8182 ?\u957 \'ed\plain \f1\lang1033\fs24   (!) \plain \f2\lang1032\fs24 \u7936 ?\u961 \'f1\u953 \'e9\u952 \'e8\plain \f1\lang1033\fs24  \-\plain \f2\lang1032\fs24 \u956 \'ec\u8183 ?\plain \f1\lang1033\fs24 . \endash  Vgl. \plain \f1\scaps\lang1033\fs24 Megna\plain \f1\lang1033\fs24 , a. O., S. 376 (Anm. 9), 382. }

