\pard\sl360\slmult1\fi0\li0\tx420\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24  4. (ff. 28r\endash 49v; f. 50r) {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Hermogenes Tarsensis}}\plain \f1\lang1033\fs24 , \u8249 \'8bDe statibus\u8250 \'9b mit Scholien (Ms. ohne Titel), ed. \plain \f1\scaps\lang1033\fs24 Rabe\plain \f1\lang1033\fs24 , Hermo\-genis opera (s. \plain \f1\i\lang1033\fs24  Lit\plain \f1\lang1033\fs24 ), S. 28\endash 92. Die letzten Textzeilen (\plain \f1\scaps\lang1033\fs24 Rabe\plain \f1\lang1033\fs24 , S. 92, 6 \plain \f2\lang1032\fs24 \u948 \'e4\u951 \'e7\u955 \'eb\u945 \'e1\u948 \'e4\plain \f1\lang1033\fs24  \u8052 ? \plain \f2\lang1032\fs24 \u960 \'f0\u949 \'e5\u957 \'ed\plain \f1\lang1033\fs24  \u8055 ?\plain \f2\lang1032\fs24 \u945 \'e1\u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u960 \'f0\u961 \'f1\u959 \'ef\plain \f1\lang1033\fs24  \-\plain \f2\lang1032\fs24 \u946 \'e2\u945 \'e1\u955 \'eb\u955 \'eb\plain \f1\lang1033\fs24  \u8057 ?\-\plain \f2\lang1032\fs24 \u956 \'ec\u949 \'e5\u957 \'ed\u959 \'ef\u962 \'f2\plain \f1\lang1033\fs24   \u8230 \'85 S. 92, 11 \u7952 ?\plain \f2\lang1032\fs24 \u966 \'f6\plain \f1\lang1033\fs24  \u8057 ?\plain \f2\lang1032\fs24 \u961 \'f1\u949 \'e5\u963 \'f3\u949 \'e5\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u964 \'f4\plain \f1\lang1033\fs24  \u8048 ? \plain \f2\lang1032\fs24 \u967 \'f7\u961 \'f1\plain \f1\lang1033\fs24  \u8059 ?\plain \f2\lang1032\fs24 \u963 \'f3\u953 \'e9\u945 \'e1\plain \f1\lang1033\fs24 ) urspr\u252 \'fcnglich vom ersten Schreiber (s. \plain \f1\i\lang1033\fs24  S\plain \f1\lang1033\fs24 , A) auf f. 50r, 1.\endash 4. Z. kopiert, sp\u228 \'e4ter aber vom zweiten Kopisten (s. \plain \f1\i\lang1033\fs24  S\plain \f1\lang1033\fs24 , B) getilgt und unten auf f. 49v geschrieben (s. auch Nr. 3). \endash  Auf ff. 23r\endash 27v (s. unten) sowie am Rand (durchgehend ab f. 33r) \u8249 \'8b{\field{\*\fldinst HYPERLINK "hida://bezper[1].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Maxi\-mus Pla\-nudes}}\plain \f1\lang1033\fs24 , Scholia in Hermogenis De statibus\u8250 \'9b, ed. \plain \f1\scaps\lang1033\fs24 Walz \plain \f1\lang1033\fs24  (s. \plain \f1\i\lang1033\fs24  Lit\plain \f1\lang1033\fs24 ), V, S. 232\endash 363. Scholien meist durch Trennzeichen und Spatium voneinander abgesetzt und in roter Tinte nummeriert. Einige interlineare Glossen und Scholien. \endash  Auf ff. 28r und 30r\endash 31r weitere anonyme, nicht komplett entzifferbare Randscholien zu \u8249 \'8bDe statibus; cap. 1\endash 2\u8250 \'9b. \endash  (f. 28r) erstes Scholion (zu \plain \f1\scaps\lang1033\fs24 Rabe\plain \f1\lang1033\fs24 , S. 28, 11\endash 12 \plain \f2\lang1032\fs24 \u960 \'f0\u949 \'e5\u961 \'f1\plain \f1\lang1033\fs24  \u8054 ? \plain \f2\lang1032\fs24 \u948 \'e4\plain \f1\lang1033\fs24  \u8050 ? \plain \f2\lang1032\fs24 \u964 \'f4\plain \f1\lang1033\fs24  \u8134 ?\plain \f2\lang1032\fs24 \u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u964 \'f4\plain \f1\lang1033\fs24  \u8182 ?\plain \f2\lang1032\fs24 \u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u960 \'f0\u959 \'ef\u955 \'eb\u953 \'e9\plain \f1\lang1033\fs24  \-\plain \f2\lang1032\fs24 \u964 \'f4\u953 \'e9\u954 \'ea\plain \f1\lang1033\fs24  \u8182 ?\plain \f2\lang1032\fs24 \u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u950 \'e6\u951 \'e7\u964 \'f4\u951 \'e7\plain \f1\lang1033\fs24  \-\plain \f2\lang1032\fs24 \u956 \'ec\plain \f1\lang1033\fs24  \u8049 ?\plain \f2\lang1032\fs24 \u964 \'f4\u969 \'f9\u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u948 \'e4\u953 \'e9\u945 \'e1\u953 \'e9\u961 \'f1\plain \f1\lang1033\fs24  \u8051 ?\-\plain \f2\lang1032\fs24 \u963 \'f3\u949 \'e5\u969 \'f9\u962 \'f2\plain \f1\lang1033\fs24 ); \plain \f1\i\lang1033\fs24  inc.\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://5650[0].5666v/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 \u916 ?\u953 ?\u8057 ?\u964 t\u953 ? \u7952 ?\u957 ? \u945 a\u8016 ?\u964 t\u8183 ? \u964 t\u8048 ? \u960 p\u959 ?\u955 ?\u953 ?\u964 t\u953 ?\u954 ?\u8048 ? \u950 ?\u951 ?\u964 t\u8053 ?\u956 \'b5\u945 a\u964 t\u945 a \u949 e\u7984 ?\u962 ? \u964 t\u8048 ? \u954 ?\u949 e\u966 f\u8049 ?\u955 ?\u945 a\u953 ?\u945 a \u948 d\u953 ?\u945 a\u953 ?\u961 ?\u949 e\u8150 ?\u964 t\u945 a\u953 ? \u954 ?\u964 t\u955 ?.}}\plain \f1\lang1033\fs24   \plain \f1\i\lang1033\fs24  des.\plain \f1\lang1033\fs24   \u7957 ?\plain \f2\lang1032\fs24 \u954 \'ea\u945 \'e1\u963 \'f3\u964 \'f4\u959 \'ef\u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u964 \'f4\plain \f1\lang1033\fs24  \u8182 ?\plain \f2\lang1032\fs24 \u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u949 \'e5\plain \f1\lang1033\fs24  \u7988 ?\plain \f2\lang1032\fs24 \u948 \'e4\u969 \'f9\u957 \'ed\plain \f1\lang1033\fs24 . \endash  (f. 31r) letztes Scholion (zu \plain \f1\scaps\lang1033\fs24 Rabe\plain \f1\lang1033\fs24 , S. 38, 11 \u8033 ?\plain \f2\lang1032\fs24 \u962 \'f2\plain \f1\lang1033\fs24   \u7936 ?\plain \f2\lang1032\fs24 \u948 \'e4\plain \f1\lang1033\fs24  \u8055 ?\plain \f2\lang1032\fs24 \u954 \'ea\u951 \'e7\u956 \'ec\u945 \'e1\plain \f1\lang1033\fs24   \u8001 ? \plain \f2\lang1032\fs24 \u966 \'f6\u949 \'e5\plain \f1\lang1033\fs24  \u8059 ?\plain \f2\lang1032\fs24 \u947 \'e3\u969 \'f9\u957 \'ed\plain \f1\lang1033\fs24 ); \plain \f1\i\lang1033\fs24  inc.\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://5650[1].5666v/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 \u932 ?\u8056 ? \u8222 \'84\u8033 ?\u962 ?\ldblquote  \u959 ?\u8016 ?\u954 ? \u7936 ?\u961 ?\u947 ?\u8056 ?\u957 ? \u954 ?\u949 e\u8150 ?\u964 t\u945 a\u953 ? \u954 ?\u964 t\u955 ?.}}\plain \f1\lang1033\fs24   \plain \f1\i\lang1033\fs24  des.\plain \f1\lang1033\fs24   \u7936 ?\plain \f2\lang1032\fs24 \u955 \'eb\u955 \'eb\plain \f1\lang1033\fs24  \rquote  \u8001 ?\plain \f2\lang1032\fs24 \u956 \'ec\u959 \'ef\u953 \'e9\u959 \'ef\plain \f1\lang1033\fs24  \u8166 ?\plain \f2\lang1032\fs24 \u957 \'ed\plain \f1\lang1033\fs24   \u7936 ?\plain \f2\lang1032\fs24 \u948 \'e4\u953 \'e9\u954 \'ea\plain \f1\lang1033\fs24  \u8053 ?\-\plain \f2\lang1032\fs24 \u956 \'ec\u945 \'e1\u964 \'f4\u953 \'e9\plain \f1\lang1033\fs24 .
\par \pard\sl360\slmult1\fi0\li0\tx420\ql\ri0\sb0\sa0\itap0 \tab Davor: (ff. 21r\endash 22v) \u8249 \'8b\plain \f1\b\lang1033\fs24  Maximus\plain \f1\lang1033\fs24   \plain \f1\b\lang1033\fs24  Planudes\plain \f1\lang1033\fs24  \u8250 \'9b, Prolegomena in \u8249 \'8bHermogenis\u8250 \'9b De statibus (Ms. \plain \f2\lang1032\fs24 \u928 \'d0\u961 \'f1\u959 \'ef\plain \f1\lang1033\fs24  \-\plain \f2\lang1032\fs24 \u955 \'eb\u949 \'e5\u947 \'e3\plain \f1\lang1033\fs24  \u8057 ?\-\plain \f2\lang1032\fs24 \u956 \'ec\u949 \'e5\u957 \'ed\u945 \'e1\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u964 \'f4\plain \f1\lang1033\fs24  \u8182 ?\plain \f2\lang1032\fs24 \u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u963 \'f3\u964 \'f4\plain \f1\lang1033\fs24  \u8049 ?\-\plain \f2\lang1032\fs24 \u963 \'f3\u949 \'e5\u969 \'f9\u957 \'ed\plain \f1\lang1033\fs24 ), ed. \plain \f1\scaps\lang1033\fs24 Walz\plain \f1\lang1033\fs24 , a. O., V, S. 222\endash 230, u. a. nach dieser Hs. \endash  Anschlie\u223 \'dfend: (f. 22v) Quomodo \plain \f2\lang1032\fs24 \u963 \'f3\u964 \'f4\plain \f1\lang1033\fs24  \u8049 ?\plain \f2\lang1032\fs24 \u963 \'f3\u949 \'e5\u953 \'e9\u962 \'f2\plain \f1\lang1033\fs24   cognoscendae sint (Ms. \plain \f2\lang1032\fs24 \u928 \'d0\plain \f1\lang1033\fs24  \u8182 ?\plain \f2\lang1032\fs24 \u962 \'f2\plain \f1\lang1033\fs24   \u7952 ?\plain \f2\lang1032\fs24 \u960 \'f0\u953 \'e9\plain \f1\lang1033\fs24  \-\plain \f2\lang1032\fs24 \u947 \'e3\u957 \'ed\u969 \'f9\u963 \'f3\plain \f1\lang1033\fs24  \u8057 ?\-\plain \f2\lang1032\fs24 \u956 \'ec\u949 \'e5\u952 \'e8\u945 \'e1\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u964 \'f4\plain \f1\lang1033\fs24  \u8048 ?\plain \f2\lang1032\fs24 \u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u963 \'f3\u964 \'f4\plain \f1\lang1033\fs24  \u8049 ?\plain \f2\lang1032\fs24 \u963 \'f3\u949 \'e5\u953 \'e9\u962 \'f2\plain \f1\lang1033\fs24 ), ed. \plain \f1\scaps\lang1033\fs24 Walz\plain \f1\lang1033\fs24 , a. O., V, S. 231; ed. \plain \f1\scaps\lang1033\fs24 Patillon \plain \f1\lang1033\fs24  (s. \plain \f1\i\lang1033\fs24  Lit\plain \f1\lang1033\fs24 ), S. XXII\endash XXIII. Darunter schematische Darstellung der \plain \f2\lang1032\fs24 \u963 \'f3\u964 \'f4\plain \f1\lang1033\fs24  \u8049 ?\plain \f2\lang1032\fs24 \u963 \'f3\u949 \'e5\u953 \'e9\u962 \'f2\plain \f1\lang1033\fs24   in roter Tinte. \endash  (ff. 23r\endash 27v) \u8249 \'8b\plain \f1\b\lang1033\fs24  Maximus\plain \f1\lang1033\fs24   \plain \f1\b\lang1033\fs24  Planudes\plain \f1\lang1033\fs24 , Scholia in Hermogenis De statibus; cap. 1\endash 2\u8250 \'9b (s. oben).}

