\pard\sl360\slmult1\fi0\li0\tx360\ql\ri0\sb0\sa0\itap0 \plain \f1\b\i\lang1033\fs20 Lit\plain \f1\lang1033\fs20  \tab \plain \f1\scaps\lang1033\fs20 Stephanus-Katalog\plain \f1\lang1033\fs20 , f. 86r. \endash  \plain \f1\scaps\lang1033\fs20 H\plain \f1\scaps\lang1033\fs20 \u246 \'f6\plain \f1\scaps\lang1033\fs20 rwarth\plain \f1\lang1033\fs20 , S. 52. \endash  \plain \f1\scaps\lang1033\fs20 Hardt\plain \f1\lang1033\fs20   III, S. 139\endash 149. \endash  \plain \f1\scaps\lang1033\fs20 Krumbacher\plain \f1\lang1033\fs20 , S. 176 (Nr. 10). \endash  \plain \f1\scaps\lang1033\fs20 P. Marc\plain \f1\lang1033\fs20 , Rez. \plain \f2\lang1032\fs20 \u925 \'cd\plain \f1\lang1033\fs20  \u8051 ?\plain \f2\lang1032\fs20 \u959 \'ef\u962 \'f2\plain \f1\lang1033\fs20   \u7961 ?\plain \f2\lang1032\fs20 \u955 \'eb\u955 \'eb\u951 \'e7\u957 \'ed\u959 \'ef\u956 \'ec\u957 \'ed\plain \f1\lang1033\fs20  \u8053 ?\plain \f2\lang1032\fs20 \u956 \'ec\u969 \'f9\u957 \'ed\plain \f1\lang1033\fs20   \u7952 ?\plain \f2\lang1032\fs20 \u954 \'ea\u948 \'e4\u953 \'e9\u948 \'e4\plain \f1\lang1033\fs20 . \u8017 ?\plain \f2\lang1032\fs20 \u960 \'f0\plain \f1\lang1033\fs20  \u8056 ? \plain \f2\scaps\lang1032\fs20 \u931 \'d3\u960 \'f0\u965 \'f5\u961 \'f1\plain \f1\scaps\lang1033\fs20 . \plain \f2\scaps\lang1032\fs20 \u928 \'d0\plain \f1\scaps\lang1033\fs20 . \plain \f2\scaps\lang1032\fs20 \u923 \'cb\u945 \'e1\u956 \'ec\u960 \'f0\u961 \'f1\u959 \'ef\u965 \'f5\plain \f1\scaps\lang1033\fs20 , \plain \f1\lang1033\fs20  in: BZ 14 (1905), S. 379\plain \f1\scaps\lang1033\fs20 .\plain \f1\lang1033\fs20   \endash  \plain \f1\scaps\lang1033\fs20 Vogel / Gardthausen\plain \f1\lang1033\fs20 , S. 14. \endash  \plain \f1\scaps\lang1033\fs20 Vorst / Delehaye\plain \f1\lang1033\fs20 , S. 117\endash 119. \endash  \plain \f1\scaps\lang1033\fs20 Hartig\plain \f1\lang1033\fs20 , S. 136, 243, 368. \endash  \plain \f1\scaps\lang1033\fs20 Ehrhard\plain \f1\lang1033\fs20 , \u220 \'dcberlie\-ferung III, S. 578\endash 580 (Beschreibung der Hs.), 582, 589, 592, 594, 595, 601\endash 602 mit Anm. 2, 605 (Anm. 2), 609, 614 (Anm. 3), 615 (Anm. 2), 616 (Anm. 2), 618\endash 620. \endash  \plain \f1\scaps\lang1033\fs20 Schunke\plain \f1\lang1033\fs20 , Renaissanceeinb\u228 \'e4nde, S. 173. \endash  \plain \f1\scaps\lang1033\fs20 Mondrain\plain \f1\lang1033\fs20 , S. \u8249 \'8b372\u8250 \'9b. \endash  \plain \f1\scaps\lang1033\fs20 Hajd\plain \f1\scaps\lang1033\fs20 \u250 \'fa\plain \f1\scaps\lang1033\fs20 , \plain \f1\lang1033\fs20  Sammlung, S. 26 (Anm. 37), 55. \endash  \plain \f1\scaps\lang1033\fs20 P. Tzivara\plain \f1\lang1033\fs20 , \u8009 ?\plain \f2\lang1032\fs20 \u956 \'ec\plain \f1\lang1033\fs20  \u8061 ?\plain \f2\lang1032\fs20 \u957 \'ed\u965 \'f5\u956 \'ec\u959 \'ef\u953 \'e9\plain \f1\lang1033\fs20   \plain \f2\lang1032\fs20 \u947 \'e3\u961 \'f1\u945 \'e1\u966 \'f6\u949 \'e5\plain \f1\lang1033\fs20  \u8150 ?\plain \f2\lang1032\fs20 \u962 \'f2\plain \f1\lang1033\fs20   \plain \f2\lang1032\fs20 \u954 \'ea\u945 \'e1\plain \f1\lang1033\fs20  \u8054 ? \plain \f2\lang1032\fs20 \u957 \'ed\u959 \'ef\u964 \'f4\plain \f1\lang1033\fs20  \u8049 ?\plain \f2\lang1032\fs20 \u961 \'f1\u953 \'e9\u959 \'ef\u953 \'e9\plain \f1\lang1033\fs20   \plain \f2\lang1032\fs20 \u963 \'f3\u964 \'f4\plain \f1\lang1033\fs20  \u8056 ?\plain \f2\lang1032\fs20 \u957 \'ed\plain \f1\lang1033\fs20   16\plain \f2\super\lang1032\fs20 \u959 \'ef\plain \f1\lang1033\fs20   \plain \f2\lang1032\fs20 \u945 \'e1\plain \f1\lang1033\fs20  \u7984 ?\u8061 ?\plain \f2\lang1032\fs20 \u957 \'ed\u945 \'e1\plain \f1\lang1033\fs20 : \u7969 ? \plain \f2\lang1032\fs20 \u960 \'f0\u949 \'e5\u961 \'f1\plain \f1\lang1033\fs20  \u8055 ?\plain \f2\lang1032\fs20 \u960 \'f0\u964 \'f4\u969 \'f9\u963 \'f3\u951 \'e7\plain \f1\lang1033\fs20   \plain \f2\lang1032\fs20 \u964 \'f4\u959 \'ef\plain \f1\lang1033\fs20  \u8166 ? \u7944 ?\plain \f2\lang1032\fs20 \u955 \'eb\u949 \'e5\u958 \'ee\plain \f1\lang1033\fs20  \u8055 ?\plain \f2\lang1032\fs20 \u959 \'ef\u965 \'f5\plain \f1\lang1033\fs20   \plain \f2\lang1032\fs20 \u932 \'d4\u961 \'f1\u959 \'ef\u965 \'f5\u956 \'ec\u960 \'f0\plain \f1\lang1033\fs20  \u8049 ?\plain \f2\lang1032\fs20 \u964 \'f4\u950 \'e6\u951 \'e7\plain \f1\lang1033\fs20 , in: \plain \f2\lang1032\fs20 \u920 \'c8\u951 \'e7\u963 \'f3\u945 \'e1\u965 \'f5\plain \f1\lang1033\fs20  \-\plain \f2\lang1032\fs20 \u961 \'f1\plain \f1\lang1033\fs20  \u8055 ?\plain \f2\lang1032\fs20 \u963 \'f3\u956 \'ec\u945 \'e1\u964 \'f4\u945 \'e1\plain \f1\lang1033\fs20   43 (2013 [2014]), S. 155\endash 175, hier 155\endash 157, 170, 175. \endash \plain \f1\scaps\lang1033\fs20  Uthemann\plain \f1\lang1033\fs20 , Anastasios Sinaites, S. 793, 797.}

