\pard\sl360\slmult1\fi0\li0\tx360\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24  10. (ff. 264v\endash 270v) In feriam quartam II \u8249 \'8bQuadragesimae\u8250 \'9b (Ms. \plain \f2\lang1032\fs24 \u932 \'d4\plain \f1\lang1033\fs24  \u8135 ? \plain \f2\lang1032\fs24 \u948 \'e4\plain \f1\lang1033\fs24  \u180 \'b4 \plain \f2\lang1032\fs24 \u964 \'f4\plain \f1\lang1033\fs24  \u8134 ?\plain \f2\lang1032\fs24 \u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u946 \'e2\plain \f1\lang1033\fs24  \u180 \'b4 \u7953 ?\plain \f2\lang1032\fs24 \u946 \'e2\u948 \'e4\u959 \'ef\u956 \'ec\plain \f1\lang1033\fs24  \u8049 ?\plain \f2\lang1032\fs24 \u948 \'e4\u959 \'ef\u962 \'f2\u903 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u955 \'eb\plain \f1\lang1033\fs24  \u8057 ?\plain \f2\lang1032\fs24 \u947 \'e3\u959 \'ef\u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u963 \'f3\u965 \'f5\u955 \'eb\u955 \'eb\u949 \'e5\u947 \'e3\plain \f1\lang1033\fs24  \u8057 ?\-\plain \f2\lang1032\fs24 \u956 \'ec\u949 \'e5\u957 \'ed\u959 \'ef\u962 \'f2\plain \f1\lang1033\fs24   \u7952 ?\plain \f2\lang1032\fs24 \u954 \'ea\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u960 \'f0\u959 \'ef\u955 \'eb\u955 \'eb\plain \f1\lang1033\fs24  \u8182 ?\plain \f2\lang1032\fs24 \u957 \'ed\plain \f1\lang1033\fs24 ); \plain \f1\i\lang1033\fs24  inc.\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://5650[0].5666v/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 \u915 G\u961 ?\u8049 ?\u966 f\u949 e\u953 ? \u8001 ? \u922 ?\u8059 ?\u961 ?\u953 ?\u959 ?\u962 ? \u7969 ?\u956 \'b5\u8182 ?\u957 ? \u7992 ?\u951 ?\u963 s\u959 ?\u8166 ?\u962 ? \u935 ?\u961 ?\u953 ?\u963 s\u964 t\u8056 ?\u962 ? \u7952 ?\u957 ? \u964 t\u8183 ? \u949 e\u7984 ?\u954 ?\u959 ?\u963 s\u964 t\u8183 ? \u964 t\u949 e\u964 t\u8049 ?\u961 ?\u964 t\u8179 ? \u954 ?\u949 e\u966 f\u945 a\u955 ?\u945 a\u8055 ?\u8179 ? \u964 t\u959 ?\u8166 ? \u917 ?\u8016 ?\u945 a\u947 ?\u947 ?\u949 e\u955 ?\u953 ?\u963 s\u964 t\u959 ?\