\fs24 \u956 \'ec\u957 \'ed\plain \f1\lang1033\fs24  \u8053 ?\plain \f2\lang1032\fs24 \u956 \'ec\u951 \'e7\u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u920 \'c8\u949 \'e5\u959 \'ef\plain \f1\lang1033\fs24  \u8166 ?); \plain \f1\i\lang1033\fs24  inc.\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://5650[0].5666v/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 \u7992 ?\u948 d\u959 ?\u8058 ? \u967 ?\u8049 ?\u961 ?\u953 ?\u964 t\u953 ? \u935 ?\u961 ?\u953 ?\u963 s\u964 t\u959 ?\u8166 ? \u949 e\u7984 ?\u962 ? \u964 t\u8052 ?\u957 ? \u964 t\u961 ?\u8055 ?\u964 t\u951 ?\u957 ? \u7953 ?\u946 \'df\u948 d\u959 ?\u956 \'b5\u8049 ?\u948 d\u945 a\u957 ? \u954 ?\u945 a\u964 t\u951 ?\u957 ?\u964 t\u8053 ?\u963 s\u945 a\u956 \'b5\u949 e\u957 ? \u964 t\u8134 ?\u962 ? \u7937 ?\u947 ?\u8055 ?\u945 a\u962 ? \u954 ?\u945 a\u8054 ? \u956 \'b5\u949 e\u947 ?\u8049 ?\u955 ?\u951 ?\u962 ? \u932 ?\u949 e\u963 s\u963 s\u945 a\u961 ?\u945 a\-\u954 ?\u959 ?\u963 s\u964 t\u8134 ?\u962 ? \u954 ?\u964 t\u955 ?.}}\plain \f1\lang1033\fs24   \plain \f1\i\lang1033\fs24  des.\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u960 \'f0\plain \f1\lang1033\fs24  \u8182 ?\plain \f2\lang1032\fs24 \u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u954 \'ea\u945 \'e1\plain \f1\lang1033\fs24  \u8054 ? \u7969 ?\plain \f2\lang1032\fs24 \u956 \'ec\plain \f1\lang1033\fs24  \u8118 ?\plain \f2\lang1032\fs24 \u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u959 \'ef\plain \f1\lang1033\fs24  \u8016 ?\plain \f2\lang1032\fs24 \u954 \'ea\plain \f1\lang1033\fs24   \u8032 ?\plain \f2\lang1032\fs24 \u966 \'f6\u949 \'e5\u955 \'eb\plain \f1\lang1033\fs24  \u8053 ?\plain \f2\lang1032\fs24 \u963 \'f3\u949 \'e5\u953 \'e9\plain \f1\lang1033\fs24   \u8017 ?\plain \f2\lang1032\fs24 \u960 \'f0\plain \f1\lang1033\fs24  \u8050 ?\plain \f2\lang1032\fs24 \u961 \'f1\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u964 \'f4\plain \f1\lang1033\fs24  \u8182 ?\plain \f2\lang1032\fs24 \u957 \'ed\plain \f1\lang1033\fs24   \u7937 ?\plain \f2\lang1032\fs24 \u956 \'ec\u945 \'e1\u961 \'f1\u964 \'f4\u953 \'e9\plain \f1\lang1033\fs24  \u8182 ?\plain \f2\lang1032\fs24 \u957 \'ed\plain \f1\lang1033\fs24   \u7969 ?\plain \f2\lang1032\fs24 \u956 \'ec\plain \f1\lang1033\fs24  \u8182 ?\plain \f2\lang1032\fs24 \u957 \'ed\plain \f1\lang1033\fs24 , \u8005 ?\plain \f2\lang1032\fs24 \u964 \'f4\u945 \'e1\u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u960 \'f0\u959 \'ef\u953 \'e9\u959 \'ef\plain \f1\lang1033\fs24  \u8166 ?\plain \f2\lang1032\fs24 \u956 \'ec\u949 \'e5\u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u945 \'e1\plain \f1\lang1033\fs24  \u8016 ?\plain \f2\lang1032\fs24 \u964 \'f4\plain \f1\lang1033\fs24  \u8052 ?\plain \f2\lang1032\fs24 \u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u954 \'ea\u945 \'e1\u952 \'e8\u945 \'e1\u961 \'f1\plain \f1\lang1033\fs24  \u8182 ?\plain \f2\lang1032\fs24 \u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u954 \'ea\u945 \'e1\plain \f1\lang1033\fs24  \u8054 ? \plain \f2\lang1032\fs24 \u949 \'e5\plain \f1\lang1033\fs24  \u8016 ?\plain \f2\lang1032\fs24 \u945 \'e1\u961 \'f1\plain \f1\lang1033\fs24  \u8051 ?\plain \f2\lang1032\fs24 \u963 \'f3\u964 \'f4\u969 \'f9\u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u964 \'f4\plain \f1\lang1033\fs24  \u8183 ? \plain \f2\lang1032\fs24 \u920 \'c8\u949 \'e5\plain \f1\lang1033\fs24  \u8183 ?, \u7975 ?\plain \f2\lang1032\fs24 \u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u947 \'e3\plain \f1\lang1033\fs24  \u8051 ?\plain \f2\lang1032\fs24 \u957 \'ed\u959 \'ef\u953 \'e9\u964 \'f4\u959 \'ef\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u960 \'f0\plain \f1\lang1033\fs24  \u8049 ?\plain \f2\lang1032\fs24 \u957 \'ed\u964 \'f4\u945 \'e1\u962 \'f2\plain \f1\lang1033\fs24   \u7969 ?\plain \f2\lang1032\fs24 \u956 \'ec\plain \f1\lang1033\fs24  \u8118 ?\plain \f2\lang1032\fs24 \u962 \'f2\plain \f1\lang1033\fs24   \u7952 ?\plain \f2\lang1032\fs24 \u960 \'f0\u953 \'e9\plain \f1\lang1033\fs24  \-\plain \f2\lang1032\fs24 \u964 \'f4\u965 \'f5\u967 \'f7\u949 \'e5\plain \f1\lang1033\fs24  \u8150 ?\plain \f2\lang1032\fs24 \u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u964 \'f4\plain \f1\lang1033\fs24  \u8134 ?\plain \f2\lang1032\fs24 \u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u956 \'ec\u949 \'e5\u961 \'f1\plain \f1\lang1033\fs24  \u8055 ?\plain \f2\lang1032\fs24 \u948 \'e4\u959 \'ef\u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u964 \'f4\plain \f1\lang1033\fs24  \u8182 ?\plain \f2\lang1032\fs24 \u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u963 \'f3\u969 \'f9\u950 \'e6\u969 \'f9\plain \f1\lang1033\fs24  \-\plain \f2\lang1032\fs24 \u956 \'ec\plain \f1\lang1033\fs24  \u8051 ?\plain \f2\lang1032\fs24 \u957 \'ed\u969 \'f9\u957 \'ed\plain \f1\lang1033\fs24   \u7952 ?\plain \f2\lang1032\fs24 \u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u935 \'d7\u961 \'f1\u953 \'e9\u963 \'f3\u964 \'f4\plain \f1\lang1033\fs24  \u8183 ? \u7992 ?\plain \f2\lang1032\fs24 \u951 \'e7\u963 \'f3\u959 \'ef\plain \f1\lang1033\fs24  \u8166 ? \plain \f2\lang1032\fs24 \u964 \'f4\plain \f1\lang1033\fs24  \u8183 ? \plain \f2\lang1032\fs24 \u922 \'ca\u965 \'f5\u961 \'f1\plain \f1\lang1033\fs24  \u8055 ?\u8179 ? \u7969 ?\plain \f2\lang1032\fs24 \u956 \'ec\plain \f1\lang1033\fs24  \u8182 ?\plain \f2\lang1032\fs24 \u957 \'ed\plain \f1\lang1033\fs24 , \u8103 ? \u7969 ? \plain \f2\lang1032\fs24 \u948 \'e4\plain \f1\lang1033\fs24  \u8057 ?\plain \f2\lang1032\fs24 \u958 \'ee\u945 \'e1\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u954 \'ea\u964 \'f4\u955 \'eb\plain \f1\lang1033\fs24 ., vgl. \plain \f1\scaps\lang1033\fs24 Ehrhard\plain \f1\lang1033\fs24 , \u220 \'dcberlieferung III, S. 570 (Nr. 64).}

