\pard\sl360\slmult1\fi0\li0\tx360\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24  14. (ff. 285r\endash 290r) In feriam quartam III \u8249 \'8bQuadragesimae\u8250 \'9b (Ms. \plain \f2\lang1032\fs24 \u932 \'d4\plain \f1\lang1033\fs24  \u8135 ? \plain \f2\lang1032\fs24 \u948 \'e4\plain \f1\lang1033\fs24  \u180 \'b4 \plain \f2\lang1032\fs24 \u964 \'f4\plain \f1\lang1033\fs24  \u8134 ?\plain \f2\lang1032\fs24 \u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u964 \'f4\u961 \'f1\plain \f1\lang1033\fs24  \u8055 ?\plain \f2\lang1032\fs24 \u964 \'f4\u951 \'e7\u962 \'f2\plain \f1\lang1033\fs24   \u7953 ?\plain \f2\lang1032\fs24 \u946 \'e2\u948 \'e4\u959 \'ef\u956 \'ec\plain \f1\lang1033\fs24  \u8049 ?\plain \f2\lang1032\fs24 \u948 \'e4\u959 \'ef\u962 \'f2\u903 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u955 \'eb\plain \f1\lang1033\fs24  \u8057 ?\plain \f2\lang1032\fs24 \u947 \'e3\u959 \'ef\u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u948 \'e4\u953 \'e9\u948 \'e4\u945 \'e1\u963 \'f3\u954 \'ea\u945 \'e1\plain \f1\lang1033\fs24  \-\plain \f2\lang1032\fs24 \u955 \'eb\u953 \'e9\u954 \'ea\plain \f1\lang1033\fs24  \u8056 ?\plain \f2\lang1032\fs24 \u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u960 \'f0\u949 \'e5\u961 \'f1\plain \f1\lang1033\fs24  \u8054 ? \plain \f2\lang1032\fs24 \u957 \'ed\u951 \'e7\u963 \'f3\u964 \'f4\u949 \'e5\plain \f1\lang1033\fs24  \u8055 ?\plain \f2\lang1032\fs24 \u945 \'e1\u962 \'f2\plain \f1\lang1033\fs24 ); \plain \f1\i\lang1033\fs24  inc.\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://5650[0].5666v/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 \u7983 ?\u954 ?\u949 e\u957 ? \u7969 ?\u956 \'b5\u8150 ?\u957 ? \u963 s\u8053 ?\u956 \'b5\u949 e\u961 ?\u959 ?\u957 ? \u7993 ?\u949 e\u961 ?\u949 e\u956 \'b5\u8055 ?\u945 a\u962 ? \u8001 ? \u960 p\u961 ?\u959 ?\u966 f\u8053 ?\u964 t\u951 ?\u962 ?, \u8001 ? \u964 t\u959 ?\u8058 ?\u962 ? \u957 ?\u945 a\u959 ?\u8058 ?\u962 ? \u960 p\u945 a\u961 ?\u945 a\u963 s\u954 ?\u949 e\u965 ?\u8049 ?\u950 ?\u969 ?\u957 ? \u964 t\u959 ?\u8166 ? \u946 \'df\u945 a\u963 s\u953 ?\u955 ?\u8051 ?\u969 ?\u962 ? \u964 t\u959 ?\u8166 ? \u956 \'b5\u949 e\u947 ?\u8049 ?\u955 ?\u959 ?\u965 ? \u954 ?\u945 a\u8054 ? \u7952 ?\u960 p\u959 ?\u965 ?\u961 ?\u945 a\u957 ?\u8055 ?\u959 ?\u965 ? \u954 ?\u964 t\u955 ?.}}\plain \f1\lang1033\fs24   \plain \f1\i\lang1033\fs24  des.\plain \f1\lang1033\fs24   \u8005 ?\plain \f2\lang1032\fs24 \u964 \'f4\u953 \'e9\plain \f1\lang1033\fs24   \u7969 ? \plain \f2\lang1032\fs24 \u952 \'e8\u949 \'e5\plain \f1\lang1033\fs24  \u8055 ?\plain \f2\lang1032\fs24 \u945 \'e1\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u915 \'c3\u961 \'f1\u945 \'e1\u966 \'f6\plain \f1\lang1033\fs24  \u8052 ? \plain \f2\lang1032\fs24 \u950 \'e6\u969 \'f9\u959 \'ef\plain \f1\lang1033\fs24  \-\plain \f2\lang1032\fs24 \u947 \'e3\u959 \'ef\u957 \'ed\u949 \'e5\plain \f1\lang1033\fs24  \u8150 ? \plain \f2\lang1032\fs24 \u954 \'ea\u945 \'e1\plain \f1\lang1033\fs24  \u8054 ? \plain \f2\lang1032\fs24 \u964 \'f4\u961 \'f1\plain \f1\lang1033\fs24  \u8051 ?\plain \f2\lang1032\fs24 \u966 \'f6\u949 \'e5\u953 \'e9\plain \f1\lang1033\fs24   \u7969 ?\plain \f2\lang1032\fs24 \u956 \'ec\plain \f1\lang1033\fs24  \u8118 ?\plain \f2\lang1032\fs24 \u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u964 \'f4\plain \f1\lang1033\fs24  \u8135 ? \plain \f2\lang1032\fs24 \u968 \'f8\u965 \'f5\u967 \'f7\plain \f1\lang1033\fs24  \u8135 ? \plain \f2\lang1032\fs24 \u954 \'ea\u945 \'e1\plain \f1\lang1033\fs24  \u8054 ? \plain \f2\lang1032\fs24 \u964 \'f4\plain \f1\lang1033\fs24  \u8183 ? \plain \f2\lang1032\fs24 \u963 \'f3\plain \f1\lang1033\fs24  \u8061 ?\plain \f2\lang1032\fs24 \u956 \'ec\u945 \'e1\u964 \'f4\u953 \'e9\plain \f1\lang1033\fs24 , \u7975 ?\plain \f2\lang1032\fs24 \u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u947 \'e3\plain \f1\lang1033\fs24  \u8051 ?\plain \f2\lang1032\fs24 \u957 \'ed\u959 \'ef\u953 \'e9\u964 \'f4\u959 \'ef\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u960 \'f0\plain \f1\lang1033\fs24  \u8049 ?\plain \f2\lang1032\fs24 \u957 \'ed\u964 \'f4\u945 \'e1\u962 \'f2\plain \f1\lang1033\fs24   \u7952 ?\plain \f2\lang1032\fs24 \u960 \'f0\u953 \'e9\plain \f1\lang1033\fs24  \-\plain \f2\lang1032\fs24 \u964 \'f4\u965 \'f5\u967 \'f7\u949 \'e5\plain \f1\lang1033\fs24  \u8150 ?\plain \f2\lang1032\fs24 \u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u949 \'e5\plain \f1\lang1033\fs24  \u7984 ?\plain \f2\lang1032\fs24 \u963 \'f3\plain \f1\lang1033\fs24  \-\plain \f2\lang1032\fs24 \u949 \'e5\u955 \'eb\u952 \'e8\u949 \'e5\plain \f1\lang1033\fs24  \u8150 ?\plain \f2\lang1032\fs24 \u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u949 \'e5\plain \f1\lang1033\fs24  \u7984 ?\plain \f2\lang1032\fs24 \u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u964 \'f4\plain \f1\lang1033\fs24  \u8052 ?\plain \f2\lang1032\fs24 \u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u945 \'e1\plain \f1\lang1033\fs24  \u7984 ?\u8061 ?\plain \f2\lang1032\fs24 \u957 \'ed\u953 \'e9\u959 \'ef\u957 \'ed\plain \f1\lang1033\fs24   \u7936 ?\plain \f2\lang1032\fs24 \u957 \'ed\plain \f1\lang1033\fs24  \u8049 ?\-\plain \f2\lang1032\fs24 \u960 \'f0\u945 \'e1\u965 \'f5\u963 \'f3\u953 \'e9\u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u967 \'f7\plain \f1\lang1033\fs24  \u8049 ?\plain \f2\lang1032\fs24 \u961 \'f1\u953 \'e9\u964 \'f4\u953 \'e9\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u935 \'d7\u961 \'f1\u953 \'e9\u963 \'f3\u964 \'f4\u959 \'ef\plain \f1\lang1033\fs24  \u8166 ? \plain \f2\lang1032\fs24 \u964 \'f4\u959 \'ef\plain \f1\lang1033\fs24  \u8166 ? \plain \f2\lang1032\fs24 \u920 \'c8\u949 \'e5\u959 \'ef\plain \f1\lang1033\fs24  \u8166 ?, \plain \f2\lang1032\fs24 \u959 \'ef\plain \f1\lang1033\fs24  \u8023 ? \u7969 ? \plain \f2\lang1032\fs24 \u948 \'e4\plain \f1\lang1033\fs24  \u8057 ?\plain \f2\lang1032\fs24 \u958 \'ee\u945 \'e1\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u954 \'ea\u964 \'f4\u955 \'eb\plain \f1\lang1033\fs24 ., vgl. \plain \f1\scaps\lang1033\fs24 Ehrhard\plain \f1\lang1033\fs24 , \u220 \'dcberlieferung III, S. 570 (Nr. 65).}

