\pard\sl360\slmult1\fi0\li0\tx360\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24  29. (ff. 350v\endash 358r) In feriam secundam VI \u8249 \'8bQuadragesimae\u8250 \'9b (Ms. \plain \f2\lang1032\fs24 \u932 \'d4\plain \f1\lang1033\fs24  \u8135 ? \plain \f2\lang1032\fs24 \u946 \'e2\plain \f1\super\lang1033\fs24 \u8115 ?\plain \f1\lang1033\fs24  \u180 \'b4 \plain \f2\lang1032\fs24 \u964 \'f4\plain \f1\lang1033\fs24  \u8134 ?\plain \f2\lang1032\fs24 \u962 \'f2\plain \f1\lang1033\fs24   \u987 ?\plain \f2\super\lang1032\fs24 \u951 \'e7\u962 \'f2\plain \f1\lang1033\fs24  \u180 \'b4 \u7953 ?\plain \f2\lang1032\fs24 \u946 \'e2\u948 \'e4\u959 \'ef\u956 \'ec\plain \f1\lang1033\fs24  \u8049 ?\plain \f2\lang1032\fs24 \u948 \'e4\u959 \'ef\u962 \'f2\u903 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u955 \'eb\plain \f1\lang1033\fs24  \u8057 ?\plain \f2\lang1032\fs24 \u947 \'e3\u959 \'ef\u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u948 \'e4\u953 \'e9\u948 \'e4\u945 \'e1\u963 \'f3\u954 \'ea\u945 \'e1\plain \f1\lang1033\fs24  \-\plain \f2\lang1032\fs24 \u955 \'eb\u953 \'e9\u954 \'ea\plain \f1\lang1033\fs24  \u8056 ?\plain \f2\lang1032\fs24 \u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u960 \'f0\u949 \'e5\u961 \'f1\plain \f1\lang1033\fs24  \u8054 ? \plain \f2\lang1032\fs24 \u956 \'ec\u949 \'e5\u964 \'f4\u945 \'e1\plain \f1\lang1033\fs24  \-\plain \f2\lang1032\fs24 \u957 \'ed\u959 \'ef\plain \f1\lang1033\fs24  \u8055 ?\plain \f2\lang1032\fs24 \u945 \'e1\u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u954 \'ea\u945 \'e1\plain \f1\lang1033\fs24  \u8054 ? \u7952 ?\plain \f2\lang1032\fs24 \u958 \'ee\plain \f1\lang1033\fs24  \-\plain \f2\lang1032\fs24 \u959 \'ef\u956 \'ec\u959 \'ef\plain \f1\lang1033\fs24  \-\plain \f2\lang1032\fs24 \u955 \'eb\u959 \'ef\u947 \'e3\plain \f1\lang1033\fs24  \u8053 ?\-\plain \f2\lang1032\fs24 \u963 \'f3\u949 \'e5\u969 \'f9\u962 \'f2\plain \f1\lang1033\fs24  \u903 ? \plain \f2\lang1032\fs24 \u949 \'e5\plain \f1\lang1033\fs24  \u8016 ?\-\plain \f2\lang1032\fs24 \u955 \'eb\plain \f1\lang1033\fs24  \u8057 ?\plain \f2\lang1032\fs24 \u947 \'e3\u951 \'e7\u963 \'f3\u959 \'ef\u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u928 \'d0\plain \f1\lang1033\fs24  \u8049 ?\plain \f2\lang1032\fs24 \u964 \'f4\u949 \'e5\u961 \'f1\plain \f1\lang1033\fs24 ); \plain \f1\i\lang1033\fs24  inc.\plain \f1\lang1033\fs24   (nach der Perikope Ps. 31, 1\endash 2) {\field{\*\fldinst HYPERLINK "hida://5650[0].5666v/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 \u934 F\u951 ?\u963 s\u8054 ?\u957 ? \u8001 ? \u956 \'b5\u945 a\u954 ?\u8049 ?\u961 ?\u953 ?\u959 ?\u962 ? \u960 p\u961 ?\u959 ?\u966 f\u8053 ?\u964 t\u951 ?\u962 ? \u916 ?\u945 a\u965 ?\u8054 ?\u948 d \u960 p\u949 e\u961 ?\u8054 ? \u964 t\u8055 ?\u957 ?\u959 ?\u962 ? \u7952 ?\u963 s\u964 t\u8054 ?\u957 ? \u959 ?\u8023 ?\u964 t\u959 ?\u962 ? \u8001 ? \u956 \'b5\u945 a\u954 ?\u945 a\u961 ?\u953 ?\u963 s\u956 \'b5\u8057 ?\u962 ? \u954 ?\u964 t\u955 ?.}}\plain \f1\lang1033\fs24   \plain \f1\i\lang1033\fs24  des.\plain \f1\lang1033\fs24   \u8033 ?\plain \f2\lang1032\fs24 \u962 \'f2\plain \f1\lang1033\fs24   \u7956 ?\plain \f2\lang1032\fs24 \u964 \'f4\u953 \'e9\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u954 \'ea\u945 \'e1\u953 \'e9\u961 \'f1\plain \f1\lang1033\fs24  \u8056 ?\plain \f2\lang1032\fs24 \u957 \'ed\plain \f1\lang1033\fs24   \u7956 ?\plain \f2\lang1032\fs24 \u967 \'f7\u969 \'f9\u956 \'ec\u949 \'e5\u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u960 \'f0\u961 \'f1\plain \f1\lang1033\fs24  \u8056 ?\plain \f2\lang1032\fs24 \u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u964 \'f4\plain \f1\lang1033\fs24  \u8052 ?\plain \f2\lang1032\fs24 \u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u956 \'ec\u949 \'e5\u964 \'f4\plain \f1\lang1033\fs24  \u8049 ?\plain \f2\lang1032\fs24 \u957 \'ed\u959 \'ef\u953 \'e9\u945 \'e1\u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u954 \'ea\u945 \'e1\plain \f1\lang1033\fs24  \u8054 ? \plain \f2\lang1032\fs24 \u964 \'f4\plain \f1\lang1033\fs24  \u8052 ?\plain \f2\lang1032\fs24 \u957 \'ed\plain \f1\lang1033\fs24   \u7952 ?\plain \f2\lang1032\fs24 \u958 \'ee\plain \f1\lang1033\fs24  \-\plain \f2\lang1032\fs24 \u959 \'ef\u956 \'ec\u959 \'ef\plain \f1\lang1033\fs24  \-\plain \f2\lang1032\fs24 \u955 \'eb\plain \f1\lang1033\fs24  \u8057 ?\plain \f2\lang1032\fs24 \u947 \'e3\u951 \'e7\u963 \'f3\u953 \'e9\u957 \'ed\plain \f1\lang1033\fs24 , \u7989 ?\plain \f2\lang1032\fs24 \u957 \'ed\u945 \'e1\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u960 \'f0\u961 \'f1\plain \f1\lang1033\fs24  \u8182 ?\plain \f2\lang1032\fs24 \u964 \'f4\u959 \'ef\u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u949 \'e5\plain \f1\lang1033\fs24  \u7988 ?\plain \f2\lang1032\fs24 \u960 \'f0\u969 \'f9\u956 \'ec\u949 \'e5\u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u964 \'f4\u945 \'e1\plain \f1\lang1033\fs24  \u8150 ?\plain \f2\lang1032\fs24 \u962 \'f2\plain \f1\lang1033\fs24   \u7937 ?\plain \f2\lang1032\fs24 \u956 \'ec\u945 \'e1\u961 \'f1\u964 \'f4\plain \f1\lang1033\fs24  \u8055 ?\plain \f2\lang1032\fs24 \u945 \'e1\u953 \'e9\u962 \'f2\plain \f1\lang1033\fs24   \u7969 ?\plain \f2\lang1032\fs24 \u956 \'ec\plain \f1\lang1033\fs24  \u8182 ?\plain \f2\lang1032\fs24 \u957 \'ed\plain \f1\lang1033\fs24 , \u7989 ?\plain \f2\lang1032\fs24 \u957 \'ed\u945 \'e1\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u948 \'e4\u953 \'e9\u954 \'ea\u945 \'e1\u953 \'e9\u969 \'f9\plain \f1\lang1033\fs24  \-\plain \f2\lang1032\fs24 \u952 \'e8\plain \f1\lang1033\fs24  \u8182 ?\plain \f2\lang1032\fs24 \u956 \'ec\u949 \'e5\u957 \'ed\plain \f1\lang1033\fs24   \u7952 ?\plain \f2\lang1032\fs24 \u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u935 \'d7\u961 \'f1\u953 \'e9\u963 \'f3\u964 \'f4\plain \f1\lang1033\fs24  \u8183 ? \u7992 ?\plain \f2\lang1032\fs24 \u951 \'e7\u963 \'f3\u959 \'ef\plain \f1\lang1033\fs24  \u8166 ? \plain \f2\lang1032\fs24 \u964 \'f4\plain \f1\lang1033\fs24  \u8183 ? \plain \f2\lang1032\fs24 \u954 \'ea\u965 \'f5\u961 \'f1\plain \f1\lang1033\fs24  \u8055 ?\u8179 ? \u7969 ?\plain \f2\lang1032\fs24 \u956 \'ec\plain \f1\lang1033\fs24  \u8182 ?\plain \f2\lang1032\fs24 \u957 \'ed\plain \f1\lang1033\fs24 , \u8103 ? \u7969 ? \plain \f2\lang1032\fs24 \u948 \'e4\plain \f1\lang1033\fs24  \u8057 ?\plain \f2\lang1032\fs24 \u958 \'ee\u945 \'e1\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u954 \'ea\u964 \'f4\u955 \'eb\plain \f1\lang1033\fs24 ., vgl. \plain \f1\scaps\lang1033\fs24 Ehrhard\plain \f1\lang1033\fs24 , \u220 \'dcberlieferung III, S. 570 (Nr. 73).}

