\pard\sl360\slmult1\fi0\li0\tx360\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24  30. (ff. 358r\endash 363r) In feriam quartam VI \u8249 \'8bQuadragesimae\u8250 \'9b (Ms. \plain \f2\lang1032\fs24 \u932 \'d4\plain \f1\lang1033\fs24  \u8135 ? \plain \f2\lang1032\fs24 \u948 \'e4\plain \f1\super\lang1033\fs24 \u8131 ?\plain \f1\lang1033\fs24  \u180 \'b4 \plain \f2\lang1032\fs24 \u964 \'f4\plain \f1\lang1033\fs24  \u8134 ?\plain \f2\lang1032\fs24 \u962 \'f2\plain \f1\lang1033\fs24   \u987 ?\u180 \'b4 \u7953 ?\plain \f2\lang1032\fs24 \u946 \'e2\u948 \'e4\u959 \'ef\u956 \'ec\plain \f1\lang1033\fs24  \u8049 ?\plain \f2\lang1032\fs24 \u948 \'e4\u959 \'ef\u962 \'f2\u903 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u955 \'eb\plain \f1\lang1033\fs24  \u8057 ?\plain \f2\lang1032\fs24 \u947 \'e3\u959 \'ef\u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u948 \'e4\u953 \'e9\u948 \'e4\u945 \'e1\u963 \'f3\u954 \'ea\u945 \'e1\plain \f1\lang1033\fs24  \-\plain \f2\lang1032\fs24 \u955 \'eb\u953 \'e9\u954 \'ea\plain \f1\lang1033\fs24  \u8056 ?\plain \f2\lang1032\fs24 \u962 \'f2\plain \f1\lang1033\fs24   \u7952 ?\plain \f2\lang1032\fs24 \u954 \'ea\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u964 \'f4\plain \f1\lang1033\fs24  \u8182 ?\plain \f2\lang1032\fs24 \u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u952 \'e8\u949 \'e5\plain \f1\lang1033\fs24  \u8055 ?\plain \f2\lang1032\fs24 \u969 \'f9\u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u915 \'c3\u961 \'f1\u945 \'e1\u966 \'f6\plain \f1\lang1033\fs24  \u8182 ?\plain \f2\lang1032\fs24 \u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u960 \'f0\u949 \'e5\u961 \'f1\plain \f1\lang1033\fs24  \u8054 ? \plain \f2\lang1032\fs24 \u956 \'ec\u949 \'e5\u964 \'f4\u945 \'e1\u957 \'ed\u959 \'ef\plain \f1\lang1033\fs24  \u8055 ?\plain \f2\lang1032\fs24 \u945 \'e1\u962 \'f2\u903 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u949 \'e5\plain \f1\lang1033\fs24  \u8016 ?\-\plain 