n \f2\lang1032\fs24 \u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u964 \'f4\plain \f1\lang1033\fs24  \u8134 ?\plain \f2\lang1032\fs24 \u962 \'f2\plain \f1\lang1033\fs24   \u8017 ?\plain \f2\lang1032\fs24 \u960 \'f0\plain \f1\lang1033\fs24  \u8050 ?\plain \f2\lang1032\fs24 \u961 \'f1\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u949 \'e5\plain \f1\lang1033\fs24  \u8016 ?\-\plain \f2\lang1032\fs24 \u955 \'eb\u959 \'ef\u947 \'e3\u951 \'e7\plain \f1\lang1033\fs24  \-\plain \f2\lang1032\fs24 \u956 \'ec\plain \f1\lang1033\fs24  \u8051 ?\plain \f2\lang1032\fs24 \u957 \'ed\u951 \'e7\u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u916 \'c4\u949 \'e5\u963 \'f3\u960 \'f0\u959 \'ef\plain \f1\lang1033\fs24  \u8055 ?\plain \f2\lang1032\fs24 \u957 \'ed\u951 \'e7\u962 \'f2\plain \f1\lang1033\fs24   \u7969 ?\plain \f2\lang1032\fs24 \u956 \'ec\plain \f1\lang1033\fs24  \u8182 ?\plain \f2\lang1032\fs24 \u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u920 \'c8\u949 \'e5\u959 \'ef\plain \f1\lang1033\fs24  \-\plain \f2\lang1032\fs24 \u964 \'f4\plain \f1\lang1033\fs24  \u8057 ?\plain \f2\lang1032\fs24 \u954 \'ea\u959 \'ef\u965 \'f5\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u954 \'ea\u945 \'e1\plain \f1\lang1033\fs24  \u8054 ? \u7936 ?\plain \f2\lang1032\fs24 \u949 \'e5\plain \f1\lang1033\fs24  \u8054 ? \plain \f2\lang1032\fs24 \u928 \'d0\u945 \'e1\u961 \'f1\u952 \'e8\plain \f1\lang1033\fs24  \u8051 ?\plain \f2\lang1032\fs24 \u957 \'ed\u959 \'ef\u965 \'f5\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u924 \'cc\u945 \'e1\u961 \'f1\plain \f1\lang1033\fs24  \u8055 ?\plain \f2\lang1032\fs24 \u945 \'e1\u962 \'f2\plain \f1\lang1033\fs24 , \u8103 ? \u7969 ? \plain \f2\lang1032\fs24 \u948 \'e4\plain \f1\lang1033\fs24  \u8057 ?\plain \f2\lang1032\fs24 \u958 \'ee\u945 \'e1\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u954 \'ea\u964 \'f4\u955 \'eb\plain \f1\lang1033\fs24 ., vgl. \plain \f1\scaps\lang1033\fs24 Ehrhard\plain \f