in \f1\lang1033\fs24  \u8054 ? \plain \f2\lang1032\fs24 \u963 \'f3\u965 \'f5\u947 \'e3\plain \f1\lang1033\fs24  \-\plain \f2\lang1032\fs24 \u967 \'f7\u969 \'f9\u961 \'f1\plain \f1\lang1033\fs24  \u8053 ?\-\plain \f2\lang1032\fs24 \u963 \'f3\u969 \'f9\u956 \'ec\u949 \'e5\u957 \'ed\plain \f1\lang1033\fs24   \u7936 ?\plain \f2\lang1032\fs24 \u955 \'eb\u955 \'eb\plain \f1\lang1033\fs24  \u8053 ?\plain \f2\lang1032\fs24 \u955 \'eb\u959 \'ef\u965 \'f5\u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u964 \'f4\plain \f1\lang1033\fs24  \u8048 ? \plain \f2\lang1032\fs24 \u960 \'f0\u964 \'f4\u945 \'e1\plain \f1\lang1033\fs24  \u8055 ?\plain \f2\lang1032\fs24 \u963 \'f3\u956 \'ec\u945 \'e1\u964 \'f4\u945 \'e1\plain \f1\lang1033\fs24 , \u7989 ?\plain \f2\lang1032\fs24 \u957 \'ed\u945 \'e1\plain \f1\lang1033\fs24   \u7952 ?\plain \f2\lang1032\fs24 \u960 \'f0\u953 \'e9\plain \f1\lang1033\fs24  \-\plain \f2\lang1032\fs24 \u964 \'f4\plain \f1\lang1033\fs24  \u8059 ?\plain \f2\lang1032\fs24 \u967 \'f7\u969 \'f9\u956 \'ec\u949 \'e5\u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u964 \'f4\plain \f1\lang1033\fs24  \u8134 ?\plain \f2\lang1032\fs24 \u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u946 \'e2\u945 \'e1\u963 \'f3\u953 \'e9\u955 \'eb\u949 \'e5\plain \f1\lang1033\fs24  \u8055 ?\plain \f2\lang1032\fs24 \u945 \'e1\u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u964 \'f4\plain \f1\lang1033\fs24  \u8182 ?\plain \f2\lang1032\fs24 \u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u959 \'ef\plain \f1\lang1033\fs24  \u8016 ?\plain \f2\lang1032\fs24 \u961 \'f1\u945 \'e1\u957 \'ed\plain \f1\lang1033\fs24  \u8182 ?\plain \f2\lang1032\fs24 \u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u954 \'ea\u964 \'f4\u955 \'eb\plain \f1\lang1033\fs24 ., vgl. \plain \f1\scaps\lang1033\fs24 Ehrhard\plain \f1\lang1033\fs24 , \u220 \'dcberlieferung III, S. 570 (Nr. 77) und 579 mit Anm. 2.; BHG 939m (Nennung der Hs.).}

