\par \pard\sl360\slmult1\fi0\li0\ql\ri0\sb0\sa0\itap0 
\par \pard\sl360\slmult1\fi0\li0\ql\ri0\sb0\sa0\itap0 1. (ff. 103v\endash 130v, 145r\endash 149v) Exzerpte aus {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Johannes Z\u228 \'e4rtel de Engelsdorf}}\plain \f1\lang1033\fs24   (?),\plain \f1\b\lang1033\fs24   \plain \f1\lang1033\fs24  Quaestiones super Aristotelis librum Priorum, vgl. \plain \f1\scaps\lang1033\fs24 Ch. H. Lohr\plain \f1\lang1033\fs24 , Medieval Latin Aristotle Commentaries, Authors: Johannes de Kanthi\endash Myngodus\plain \f1\scaps\lang1033\fs24 ,\plain \f1\scaps\lang1033\fs24  \plain \f1\lang1033\fs24  in: Traditio 27 (1971), S. 251\u8722 -351, hier S. 305; \plain \f1\scaps\lang1033\fs24 M. Markowski\plain \f1\lang1033\fs24 , Abhandlungen zur Logik an der Universit\u228 \'e4t Wien in den Jahren 1365\u8722 -1500, in: Studia mediewistyczne 22, 1 (1983), S. 53\u8722 -77, hier S. 68 und 76\endash 77.\plain \f1\i\lang1033\fs24   \plain \f1\lang1033\fs24  \endash  (ff. 103v\endash 104r) 1. Quaestio; inc. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Utrum de silogismo simpliciter possit esse scientia. Notandum primo, quod iste terminus silogismus in questione positus potest accipi duobus modis}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17  eqs.}}\plain \f1\lang1033\fs24   \endash  (ff. 104r\endash 105r) 2. Quaestio; inc. {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Utrum silogismus simpliciter sit subiectum scientie libri priorum. Notandum simpliciter in proposito}}{\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17  eqs.}}\plain \f1\lang1033\fs24   \endash  (f. 149v) Quaestio ultima; inc. {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Utrum definitio enthymematis }}{\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 (Ms. }}{\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 entimeumatis}}{\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 )}}{\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17  sit bona. Notandum pro questione quod enthymema }}\plain \f1\lang1033\fs24\chcbpat17 (Ms. {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 enthimeuma}}{\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 )}}{\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17  est nomen}}{\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17  eqs.}}\plain \f1\lang1033\fs24   des. \plain \f1\i\lang1033\fs24  nam antecedens est possibile et consequens inpossibile, modo ex possibili non sequitur inpossibile. \plain \f1\lang1033\fs24  \endash  Am Textende: \plain \f1\i\lang1033\fs24  Expliciunt questiones super libros prioris Aristotelis\plain \f1\lang1033\fs24 . Zu den einzelnen Quaestiones jeweils nur die Abschnitte \plain \f1\i\lang1033\fs24  Notandum \plain \f1\lang1033\fs24  bzw. \plain \f1\i\lang1033\fs24  Dicendum ad quaestionem \plain \f1\lang1033\fs24  wiedergegeben, vgl. ff. 158v\u8722 -175v. \endash  (f. 150r) leer.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}{\f2\fnil\fcharset161 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

\uc1
\pard\sl360\slmult1\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24  2. (ff. 131r\u8722 -143v) \u8249 \'8b\plain \f1\b\lang1033\fs24  Leonardus\plain \f1\lang1033\fs24   \plain \f1\b\lang1033\fs24  Fruman\plain \f1\lang1033\fs24   \plain \f1\b\lang1033\fs24  de\plain \f1\lang1033\fs24   \plain \f1\b\lang1033\fs24  Hirsau\plain \f1\lang1033\fs24 , Collectiones de impositione, positione et depositione secundum {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Johannis Hollandrini}}\plain \f1\lang1033\fs24   tractatum obligationum\u8250 \'9b (Ms. ohne Titel); inc. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Notandum H.}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17  (scil. Hollandrinus) }}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 ponit unam diuisionem et vult tamen de numero propositionis: Quedam est propositio ponibilis et quedam non ponibilis. Ex illo patet quod non omnis propositio est ponibilis}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17  eqs.}}\plain \f1\i\lang1033\fs24   \plain \f1\lang1033\fs24  des. \plain \f1\i\lang1033\fs24  Sortes non est asinus uel Sortes est coloratus et ergo alia distinctio est necessaria\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24  Idem est dicendum in aliis consimilibus propositionibus\plain \f1\lang1033\fs24 : \plain \f1\i\lang1033\fs24  Impositionem, positionem, depositionem.\plain \f1\lang1033\fs24   \endash  Am Textende:\plain \f1\i\lang1033\fs24   Et hec sunt collecta per egregium virum licentiatum nec non magistrum Leonardum Fruman de Hirsau\plain \f1\lang1033\fs24 . \endash  Wiederholung des Textes auf ff. 152v\endash 158r (s. Nr. 5). \endash  Es handelt sich um den Kommentar zum Traktat Obligationum et insolubilium tractatulus von Johannes Holandrinus. Ausgaben des kommentierten Werkes: \plain \f1\i\lang1033\fs24  ed. princ.\plain \f1\lang1033\fs24   Magistri Ioannis Holandrini dialectici argutissimi obligationum et insolubilium tractatulus, Wien 1509, besonders ff. b \plain \f1\scaps\lang1033\fs24 i\plain \f1\lang1033\fs24  r\endash d \plain \f1\scaps\lang1033\fs24 ii\plain \f1\lang1033\fs24  v; ed. \plain \f1\scaps\lang1033\fs24 E. P. Bos\plain \f1\lang1033\fs24 , John of Holland, Four Tracts on Logic (Suppositiones, Fallacie, Obligationes, Insolubilia) (Artistarium 5), Nijmegen 1985, S. 91\endash 110. \endash  Zu Magister Leonhard Frumann aus Hirschau, (1457 in Wien immatrikuliert; 1473, 1479, 1483, 1490 Dekan der Artistenfakult\u228 \'e4t; 1475 als baccalarius in theologia und 1485 als theologiae licentiatus jeweils Rektor der Universit\u228 \'e4t Wien) s.\plain \f1\scaps\lang1033\fs24  J. v. Aschbach, \plain \f1\lang1033\fs24  Die Wiener Universit\u228 \'e4t und ihre Humanisten im Zeitalter Kaiser Maximilians I., Wien 1877, S. 445f. und 451f.; \plain \f1\scaps\lang1033\fs24 W. Szaivert / F\plain \f1\scaps\lang1033\fs24 . Gall \plain \f1\lang1033\fs24  (Hrsg.), Die Matrikel der Universit\u228 \'e4t Wien, II: 1451\endash 1518/I: Text (Publikationen des Instituts f\u252 \'fcr \u214 \'d6sterreichische Geschichtsforschung, 6. Reihe. Quellen zur Geschichte der Universit\u228 \'e4t Wien, 1. Abteilung. Die Matrikel der Universit\u228 \'e4t Wien), Graz / Wien / K\u246 \'f6ln 1967, S. 50b, 80 (mit Anm. 1), 146, 186. Zu Johannes Hollandrinus s. Nr. 3.}

