\pard\sl360\slmult1\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24  3. (ff. 143v\endash 144r) {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Johannes Hollandrinus}}\plain \f1\lang1033\fs24 , De appetito (Ms. \plain \f1\i\lang1033\fs24  Sequitur inicium Holandrini\plain \f1\lang1033\fs24 ); inc. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Duplex est cognitio scilicet sensitiua et intellectiua et unamquamque cognitionem sequitur aliquis appetitus. Appetitus est tendencia rei in bonum existens uel apparens eqs.}}\plain \f1\i\lang1033\fs24   \plain \f1\lang1033\fs24  des. \plain \f1\i\lang1033\fs24  et iste appetitus intellectiuus vocatur voluntas\plain \f1\lang1033\fs24 . \endash  (144\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) leer. \endash  Zu Johannes Hollandrinus (s. auch Nr. 2) vgl. \plain \f1\scaps\lang1033\fs24 G. Bauch\plain \f1\lang1033\fs24 , Die Reception des Humanismus in Wien, Breslau 1903, S. 6, 109; \plain \f1\scaps\lang1033\fs24 Bos\plain \f1\lang1033\fs24   (s. Nr. 2), S. *13*\u8722 -*47*; \plain \f1\scaps\lang1033\fs24 R. Aubert\plain \f1\lang1033\fs24 , Art. Jean de Hollande, in: \plain \f1\scaps\lang1033\fs24 Ders.\plain \f1\lang1033\fs24   (Hrsg.), Dictionnaire d\rquote histoire et de g\u233 \'e9ographie eccl\u233 \'e9siastique 27 (2000), Paris 2000, Sp. 141\endash 142.}

