\par \pard\sl360\slmult1\fi0\li0\tx420\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24  \tab (f. 4v) \u8249 \'8bIn sanctam Trinitatem\u8250 \'9b (Ms. \plain \f3\lang1032\fs24 \u928 \'d0\u961 \'f1\u959 \'ef\u963 \'f3\u949 \'e5\u965 \'f5\u967 \'f7\plain \f1\lang1033\fs24  \u8052 ? \plain \f3\lang1032\fs24 \u950 \'e6\plain \f1\lang1033\fs24  \u180 \'b4\u903 ? \plain \f1\i\lang1033\fs24  7\plain \f1\lang1033\fs24 ); \plain \f1\i\lang1033\fs24  inc.\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://5650[5].5666v/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 \u8249 \'8b\u932 ?\u8250 \'9b\u961 ?\u953 ?\u8048 ?\u962 ? \u7936 ?\u956 \'b5\u8051 ?\u961 ?\u953 ?\u963 s\u964 t\u949 e \u954 ?\u945 a\u8054 ? \u7936 ?\u948 d\u953 ?\u945 a\u8055 ?\u961 ?\u949 e\u964 t\u949 e, \u7969 ?\u956 \'b5\u8118 ?\u962 ? \u7952 ?\u955 ?\u8051 ?\u951 ?\u963 s\u959 ?\u957 ? \u964 t\u959 ?\u8058 ?\u962 ? \u960 p\u961 ?\u959 ?\u963 s\u954 ?\u965 ?\u957 ?\u959 ?\u8166 ?\u957 ?\u964 t\u8049 ?\u962 ? \u963 s\u949 e \u954 ?\u964 t\u955 ?.}}\plain \f1\lang1033\fs24   \plain \f1\i\lang1033\fs24  des.\plain \f1\lang1033\fs20   \plain \f3\lang1032\fs24 \u959 \'ef\plain \f1\lang1033\fs24  \u7990 ?\plain \f3\lang1032\fs24 \u948 \'e4\u945 \'e1\u962 \'f2\plain \f1\lang1033\fs24   \u7969 ?\plain \f3\lang1032\fs24 \u956 \'ec\plain \f1\lang1033\fs24  \u8182 ?\plain \f3\lang1032\fs24 \u957 \'ed\plain \f1\lang1033\fs24   \plain \f3\lang1032\fs24 \u964 \'f4\plain \f1\lang1033\fs24  \u8052 ?\plain \f3\lang1032\fs24 \u957 \'ed\plain \f1\lang1033\fs24   \u7936 ?\plain \f3\lang1032\fs24 \u963 \'f3\u952 \'e8\plain \f1\lang1033\fs24  \u8051 ?\-\plain \f3\lang1032\fs24 \u957 \'ed\u949 \'e5\u953 \'e9\u945 \'e1\u957 \'ed\plain \f1\lang1033\fs24 . \endash  (f. 4Ar\endash v) leer. \endash  (f. 5r) \u8249 \'8bSalve Regina\u8250 \'9b (griech.); \plain \f1\i\lang1033\fs24  inc.\plain \f1\lang1033\fs24   (\plain \f1\i\lang1033\fs24  Salve, Regina, mater misericordiae, vita, dulcedo et spes nostra, salve\plain \f1\lan