\par \pard\sl360\slmult1\fi0\li0\tx420\ql\ri0\sb0\sa0\itap0 \tab (ff. 81r\endash 82r) Aus der Megale Octoechus, ed. Parakletike. \endash  \plain \f3\lang1032\fs24 \u7982 ?\u967 \'f7\u959 \'ef\u962 \'f2\plain \f1\lang1033\fs24   \plain \f3\lang1032\fs24 \u945 \'e1\plain \f1\lang1033\fs24  \u180 \'b4, Sonntag (Orthros), a. O., S. 9\endash 21: (f. 81r) \u8249 \'8b{\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Ioannes Damascenus}}\plain \f1\lang1033\fs24 , Canones anastasimi*; Canon \plain \f3\lang1032\fs24 \u931 \'d3\u959 \'ef\u8166 ?\plain \f1\lang1033\fs24   \u7969 ? \plain \f3\lang1032\fs24 \u964 \'f4\u961 \'f1\u959 \'ef\u960 \'f0\u945 \'e1\u953 \'e9\u959 \'ef\u8166 ?\u967 \'f7\u959 \'ef\u962 \'f2\plain \f1\lang1033\fs24   \plain \f3\lang1032\fs24 \u948 \'e4\u949 \'e5\u958 \'ee\u953 \'e9\u8049 ?\plain \f1\lang1033\fs24   (Ode \plain \f3\lang1032\fs24 \u945 \'e1\plain \f1\lang1033\fs24  \u180 \'b4, Theotokion)\u8250 \'9b (Ms. \plain \f3\lang1032\fs24 \u928 \'d0\u961 \'f1\u959 \'ef\u963 \'f3\u949 \'e5\u8059 ?\u967 \'f7\u945 \'e1\u953 \'e9\u962 \'f2\plain \f1\lang1033\fs24   [!] \plain \f3\lang1032\fs24 \u960 \'f0\u961 \'f1\u8056 ?\u962 \'f2\plain \f1\lang1033\fs24   \u7937 ?\plain \f3\lang1032\fs24 \u947 \'e3\u8055 ?\u945 \'e1\u957 \'ed\plain \f1\lang1033\fs24   \plain \f3\lang1032\fs24 \u920 \'c8\u949 \'e5\u959 \'ef\plain \f1\lang1033\fs24  \-\plain \f3\lang1032\fs24 \u964 \'f4\u8057 ?\u954 \'ea\u959 \'ef\u957 \'ed\plain \f1\lang1033\fs24 . Am Rand: \plain \f3\lang1032\fs24 \u945 \'e1\plain \f1\lang1033\fs24  \u180 \'b4), vgl. f. 2r. \endash  (f. 81v, 1.\endash 11. Z.) \u8249 \'8b{\field{\*\fldinst HYPERLINK "hida://bezper[1].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Cosmas Hierosolymitanus}}\plain \f1\lang1033\fs24 , Canon stauroana\-sta\-simus \plain \f3\lang1032\fs24 \u935 \'d7\u961 \'f1\u953 \'e9\u963 \'f3\u964 \'f4\u8056 ?\u962 \'f2\plain \f1\lang1033\fs24   \plain \f3\lang1032\fs24 \u947 \'e3\u949 \'e5\u957 \'ed\u957 \'ed\u8118 ?\u964 \'f4\u945 \'e1\u953 \'e9\plain \f1\lang1033\fs24 , \plain \f3\lang1032\fs24 \u948 \'e4\u959 \'ef\u958 \'ee\u8049 ?\plain \f1\lang1033\fs24  \-\plain \f3\lang1032\fs24 \u963 \'f3\u945 \'e1\u964 \'f4\u949 \'e5\plain \f1\lang1033\fs24 , Theotokion\u8250 \'9b (Ms. \plain \f3\lang1032\fs24 \u928 \'d0\u961 \'f1\u959 \'ef\u963 \'f3\u949 \'e5\u965 \'f5\u967 \'f7\plain \f1\lang1033\fs24  \u8052 ? \plain \f3\lang1032\fs24 \u946 \'e2\plain \f1\lang1033\fs24  \u180 \'b4), vgl. f. 2v. \endash  (ff. 81v, 12. Z.\endash 82r, 8. Z.) \u8249 \'8bCanon in sanctissimam Deiparam \plain \f3\lang1032\fs24 \u931 \'d3\u959 \'ef\u8166 ?\plain \f1\lang1033\fs24   \u7969 ? \plain \f3\lang1032\fs24 \u964 \'f4\u961 \'f1\u959 \'ef\u960 \'f0\u945 \'e1\u953 \'e9\u959 \'ef\u8166 ?\u967 \'f7\u959 \'ef\u962 \'f2\plain \f1\lang1033\fs24   \plain \f3\lang1032\fs24 \u948 \'e4\u949 \'e5\u958 \'ee\u953 \'e9\u8049 ?\plain \f1\lang1033\fs24 , 1. und 2. Troparion\u8250 \'9b\plain \f1\lang1033\fs20   \plain \f1\lang1033\fs24  (im Ms. als einzelne Gebete betrachtet: f. 81v, 12.\endash letzte Z. \plain \f3\lang1032\fs24 \u947 \'e3\plain \f1\lang1033\fs24  \u180 \'b4. f. 82r, 1.\endash 8. Z. \plain \f3\lang1032\fs24 \u928 \'d0\u961 \'f1\u959 \'ef\u963 \'f3\u949 \'e5\u965 \'f5\u967 \'f7\plain \f1\lang1033\fs24  \u8052 ? \plain \f3\lang1032\fs24 \u948 \'e4\plain \f1\lang1033\fs24  \u180 \'b4), vgl. f. 3r\endash 3v, 11. Z. \endash  (f. 82r, 9.\endash 17. Z.) \u8249 \'8b\plain \f1\b\lang1033\fs24  Ioannes\plain \f1\lang1033\fs24   \plain \f1\b\lang1033\fs24  Damascenus\plain \f1\lang1033\fs24 , Canones anastasimi*; Canon \plain \f3\lang1032\fs24 \u931 \'d3\u959 \'ef\u8166 ?\plain \f1\lang1033\fs24   \u7969 ? \plain \f3\lang1032\fs24 \u964 \'f4\u961 \'f1\u959 \'ef\u960 \'f0\u945 \'e1\u953 \'e9\u959 \'ef\u8166 ?\u967 \'f7\u959 \'ef\u962 \'f2\plain \f1\lang1033\fs24   \plain \f3\lang1032\fs24 \u948 \'e4\u949 \'e5\u958 \'ee\u953 \'e9\u8049 ?\plain \f1\lang1033\fs24   (Ode \plain \f3\lang1032\fs24 \u947 \'e3\plain \f1\lang1033\fs24  \u180 \'b4, Theotokion)\u8250 \'9b (Ms. \plain \f3\lang1032\fs24 \u928 \'d0\u961 \'f1\u959 \'ef\u963 \'f3\u949 \'e5\u965 \'f5\u967 \'f7\plain \f1\lang1033\fs24  \u8052 ? \plain \f3\lang1032\fs24 \u949 \'e5\plain \f1\lang1033\fs24  \u180 \'b4), vgl. f. 4r. \endash  (f. 82v, 1.\endash 4. Z.) \plain \f3\lang1032\fs24 \u7982 ?\u967 \'f7\u959 \'ef\u962 \'f2\plain \f1\lang1033\fs24   \plain \f3\lang1032\fs24 \u946 \'e2\u945 \'e1\u961 \'f1\u8059 ?\u962 \'f2\plain \f1\lang1033\fs24 , Sonntag (Orthros); \u8249 \'8bAnabathmoi, Antiphonon \plain \f3\lang1032\fs24 \u945 \'e1\plain \f1\lang1033\fs24  \u180 \'b4, 3. Troparion\u8250 \'9b (Ms. \plain \f3\lang1032\fs24 \u928 \'d0\u961 \'f1\u959 \'ef\u963 \'f3\u949 \'e5\u965 \'f5\u967 \'f7\plain \f1\lang1033\fs24  \u8052 ? \u987 ?\u180 \'b4), vgl. f. 3v, 12.\endash 16. Z.
\par \pard\sl360\slmult1\fi0\li0\tx420\ql\ri0\sb0\sa0\itap0 \tab (f. 82v, 5.\endash 13. Z.) \u8249 \'8bIn sanctam Trinitatem\u8250 \'9b (Ms. \plain \f3\lang1032\fs24 \u928 \'d0\u961 \'f1\u959 \'ef\u963 \'f3\u949 \'e5\u965 \'f5\u967 \'f7\plain \f1\lang1033\fs24  \u8052 ? \plain \f3\lang1032\fs24 \u950 \'e6\plain \f1\lang1033\fs24  \u180 \'b4), vgl. f. 4v. \endash  (f. 83r\endash v) Salve Regina, in zwei verschiedenen griech. \u220 \'dcbersetzungen: (f. 83r) Nr. 1 (Ms. ohne Titel); \plain \f1\i\lang1033\fs24  inc.\plain \f1\lang1033\fs24   (\plain \f1\i\lang1033\fs24  Salve, Regina, mater misericordiae, vita, dulcedo et spes nostra, salve\plain \f1\lang1033\fs24   etc.) {\field{\*\fldinst HYPERLINK "hida://5650[0].5666v/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 \u935 ?\u945 a\u8150 ?\u961 ?\u949 e, \u916 ?\u8051 ?\u963 s\u960 p\u959 ?\u953 ?\u957 ?\u945 a, \u924 ?\u8134 ?\u964 t\u949 e\u961 ? \u7952 ?\u955 ?\u8051 ?\u959 ?\u965 ?\u962 ?, \u950 ?\u969 ?\u8053 ?, \u947 ?\u955 ?\u965 ?\u954 ?\u8059 ?\u964 t\u951 ?\u962 ? \u954 ?\u945 a\u8054 ? \u7952 ?\u955 ?\u960 p\u8054 ?\u962 ? \u7969 ?\u956 \'b5\u8182 ?\u957 ?, \u967 ?\u945 a\u8150 ?\u961 ?\u949 e \u954 ?\u964 t\u955 ?.}}\plain \f1\lang1033\fs24   \plain \f1\i\lang1033\fs24  des. \plain \f1\lang1033\fs24  \u8038 ? \plain \f3\lang1032\fs24 \u947 \'e3\u955 \'eb\u965 \'f5\u954 \'ea\u945 \'e1\u963 \'f3\u956 \'ec\u8050 ?\plain \f1\lang1033\fs24   \plain \f3\lang1032\fs24 \u960 \'f0\u945 \'e1\u961 \'f1\u952 \'e8\u8051 ?\u957 \'ed\u949 \'e5\plain \f1\lang1033\fs24   \plain \f3\lang1032\fs24 \u924 \'cc\u945 \'e1\u961 \'f1\u953 \'e9\plain \f1\lang1033\fs24  \u8049 ?\plain \f3\lang1032\fs24 \u956 \'ec\plain \f1\lang1033\fs24 . \endash  (f. 83v) Nr. 2 (Ms. ohne Titel), vgl. f. 5r. \endash  (f. 84r): (1.\endash 2. Z.) \u8249 \'8bTrisagion\u8250 \'9b (Ms. ohne Titel), vgl. f. 5v, 1.\endash 3. Z. (3.\endash 7. Z.) \u8249 \'8bEpinikios Hymnus (Sanctus)\u8250 \'9b (Ms. ohne Titel), vgl. f. 5v, 4.\endash 9. Z. Anschlie\u223 \'dfend: (8.\endash 11. Z.) Glaubensbekenntnis (Ms. ohne Titel), vgl. f. 5v, 10.\endash 16. Z. \endash  Am Textende: \plain \f3\lang1032\fs24 \u932 \'d4\plain \f1\lang1033\fs24  \u8048 ? \plain \f3\lang1032\fs24 \u966 \'f6\plain \f1\lang1033\fs24  \u8055 ?\plain \f3\lang1032\fs24 \u955 \'eb\u969 \'f9\u957 \'ed\plain \f1\lang1033\fs24   \plain \f3\lang1032\fs24 \u954 \'ea\u959 \'ef\u953 \'e9\u957 \'ed\plain \f1\lang1033\fs24  \u8049 ?, vgl. {\field{\*\fldinst HYPERLINK "hida://bezper[2].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Plato}}\plain \f1\lang1033\fs24 , Phaedrus 279 c. Vgl. auch I. Teil, Nr. 2 (f. 5v), und X. Teil, Nr. 1 (Exzerpt 7).}

