\pard\sl360\slmult1\fi0\li0\tx360\ql\ri0\sb0\sa0\itap0 \plain \f1\b\i\lang1033\fs24 \u220 \'dc\plain \f1\lang1033\fs24  \tab Kopie der \plain \f1\i\lang1033\fs24  editio princeps\plain \f1\lang1033\fs24   (Paris: Conradus Neobarius, 1539), s. \plain \f1\scaps\lang1033\fs24 Rabe\plain \f1\lang1033\fs24   (s. \plain \f1\i\lang1033\fs24  Lit\plain \f1\lang1033\fs24 ), S. VIII.
